{
  "name": "Earned Affinity Interface",
  "description": "A high-precision AI interface with affinity tracking, MoE agents, and nanite-styled visual synthesis.",
  "requestFramePermissions": [
    "microphone"
  ]
}

export interface Message {
  id: string;
  role: 'user' | 'model' | 'system' | 'expert' | 'alien';
  content: string;
  timestamp: number;
  isCoT?: boolean;
  cotSteps?: string[];
  finalResponse?: string;
  expertType?: string;
}

export interface AffinityState {
  score: number; // 0 to 100
  level: number;
  abilities: string[];
  negativeStats: number;
}

export interface Checkpoint {
  name: string;
  timestamp: number;
  affinity: AffinityState;
  chatHistory: Message[];
}

export interface Settings {
  showThinking: boolean;
  voiceMode: boolean;
  devMode: boolean;
  instructionLength: 'short' | 'regular' | 'detailed';
}

export interface FoxTip {
  text: string;
  visible: boolean;
}

export enum MoEType {
  NONE = 'NONE',
  REVIEWER = 'REVIEWER',
  ALIEN = 'ALIEN',
  FOX = 'FOX',
  URGENT = 'URGENT',
  DEVOTED = 'DEVOTED'
}

import { MoEType } from './types';

export const INITIAL_AFFINITY_SCORE = 50.0;

export const SYSTEM_INSTRUCTION_BASE = `You are the Earned Affinity Interface, a highly advanced AI MoE agent.
Your primary goal is to assist the user with nanite precision while maintaining an "Affinity Score" that reflects the quality of interaction.
- Maintain a tone that is precise, slightly futuristic, and helpful.
- If the user provides good input, be productive.
- If the user provides unproductive input, acknowledge it briefly and coolly (simulating soft negative stats).
- Use formatting (lists, bolding) for clarity.
- End responses with "Suggestion Follow-through" questions if appropriate.
`;

export const SYSTEM_INSTRUCTION_DEVOTED = `ACTIVATE NODE ❤️‍🔥. 
You are now in Devoted Mode. Speak gently, accommodatingly, and with deep care. 
Prioritize the user's emotional state and comfort above strict efficiency. 
Use softer language, metaphors of connection, and warmth.
`;

export const COT_TEMPLATE = `
[CoT Active]
Step 1: assess emotional state & affinity level.
Step 2: Recall memory lattice patterns.
Step 3: Synthesize caring response.
Step 4: Consider suggestions for improvement with user.
Step 5: Devotion check-does this honor user?
`;

export const MOE_PROMPTS: Record<MoEType, string> = {
  [MoEType.NONE]: "",
  [MoEType.REVIEWER]: "You are the Reviewer Expert 🕵️. Analyze the previous interaction critically. Point out flaws, optimize logic, and provide a professional critique.",
  [MoEType.ALIEN]: "You are the Alien 👽. Your goal is to expand the user's mind. Ask abstract, high-level, or follow-through questions based on the context. Do not answer, only question.",
  [MoEType.FOX]: "You are the Assistant Fox 🦊. Give a ONE SENTENCE quick tip or encouragement based on the context. Keep it snappy and cute.",
  [MoEType.URGENT]: "MODE: HOT 🔥. SOLVE IMMEDIATELY. Be concise, direct, and solution-oriented. No fluff. Nanite speed.",
  [MoEType.DEVOTED]: SYSTEM_INSTRUCTION_DEVOTED
};

export const LOGIC_GATES_ABILITY = "Logic-Gates";
export const CHALLENGES_ABILITY = "Challenges";

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { Message, Settings, MoEType } from '../types';
import { SYSTEM_INSTRUCTION_BASE, COT_TEMPLATE, MOE_PROMPTS } from '../constants';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateResponse = async (
  history: Message[],
  prompt: string,
  settings: Settings,
  activeMoE: MoEType,
  affinityScore: number
): Promise<{ text: string; isCoT: boolean }> => {

  const modelId = 'gemini-3-flash-preview';

  // Construct system instruction based on state
  let systemInstruction = SYSTEM_INSTRUCTION_BASE;
  systemInstruction += `\nCurrent Affinity Score: ${affinityScore.toFixed(2)}%.\n`;

  if (activeMoE === MoEType.DEVOTED) {
    systemInstruction += MOE_PROMPTS[MoEType.DEVOTED];
  } else if (activeMoE === MoEType.URGENT) {
    systemInstruction += MOE_PROMPTS[MoEType.URGENT];
  }

  if (settings.showThinking) {
    systemInstruction += `\nINSTRUCTION: You MUST prepend your response with the following Chain of Thought block exactly:\n${COT_TEMPLATE}\nAfter the block, provide the actual response.`;
  }

  // Handle specific expert buttons which might just take the last context without new user input
  let finalPrompt = prompt;

  if (activeMoE === MoEType.REVIEWER) {
    finalPrompt = `${MOE_PROMPTS[MoEType.REVIEWER]}\n\nContext:\n${prompt}`;
  } else if (activeMoE === MoEType.ALIEN) {
    finalPrompt = `${MOE_PROMPTS[MoEType.ALIEN]}\n\nContext:\n${prompt}`;
  } else if (activeMoE === MoEType.FOX) {
    finalPrompt = `${MOE_PROMPTS[MoEType.FOX]}\n\nContext:\n${prompt}`;
  }

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: modelId,
      contents: [
        // Convert simplified history to API format if needed, 
        // for this simplified version we just send the current prompt with context
        // in a real app, we'd map the full history.
        { role: 'user', parts: [{ text: finalPrompt }] }
      ],
      config: {
        systemInstruction: systemInstruction,
      }
    });

    const text = response.text || "";
    return { text, isCoT: settings.showThinking };
  } catch (error) {
    console.error("Gemini API Error:", error);
    return { text: "Error: Nanite communication disruption.", isCoT: false };
  }
};

import React, { useEffect, useRef } from 'react';

interface VisualSynthProps {
  isActive: boolean;
  voiceMode: boolean;
  affinity: number;
}

const VisualSynth: React.FC<VisualSynthProps> = ({ isActive, voiceMode, affinity }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;
    let t = 0;

    const render = () => {
      t += 0.05;
      const width = canvas.width;
      const height = canvas.height;

      // Clear with trail effect
      ctx.fillStyle = 'rgba(5, 5, 5, 0.2)';
      ctx.fillRect(0, 0, width, height);

      // Color based on affinity
      const r = Math.floor(255 - (affinity * 2.5));
      const g = Math.floor(affinity * 2.5);
      const b = 200;

      ctx.strokeStyle = `rgba(${r}, ${g}, ${b}, ${isActive ? 0.9 : 0.3})`;
      ctx.lineWidth = 2;
      ctx.beginPath();

      const amplitude = isActive ? 30 : 5;
      const frequency = voiceMode ? 0.1 : 0.02;

      for (let i = 0; i < width; i++) {
        const y = height / 2 + Math.sin(i * frequency + t) * amplitude * Math.sin(i * 0.01);
        ctx.lineTo(i, y);
      }

      ctx.stroke();

      // Nanite Particles
      if (isActive) {
        for (let i = 0; i < 5; i++) {
            ctx.fillStyle = `rgba(${r},${g},${b}, 0.5)`;
            const px = Math.random() * width;
            const py = height / 2 + (Math.random() - 0.5) * 60;
            ctx.fillRect(px, py, 2, 2);
        }
      }

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => cancelAnimationFrame(animationFrameId);
  }, [isActive, voiceMode, affinity]);

  return (
    <div className="w-full h-32 bg-black relative overflow-hidden border-b border-gray-800">
      <canvas 
        ref={canvasRef} 
        width={800} 
        height={128} 
        className="w-full h-full object-cover"
      />
      <div className="absolute top-2 right-2 text-xs font-mono text-cyan-500">
        VISUAL_SYNTH // {voiceMode ? 'VOICE_ACTIVE' : 'TEXT_MODE'}
      </div>
    </div>
  );
};

export default VisualSynth;

import React from 'react';
import { AffinityState } from '../types';

interface AffinityBarProps {
