export default AffinityBar;

import React from 'react';
import { Settings, Message, Checkpoint } from '../types';

interface SettingsPanelProps {
  isOpen: boolean;
  type: 'history' | 'settings';
  onClose: () => void;
  settings: Settings;
  onSettingsChange: (newSettings: Settings) => void;
  history: Message[];
  checkpoints: Checkpoint[];
  onLoadCheckpoint: (name: string) => void;
  logs: string[];
}

const SettingsPanel: React.FC<SettingsPanelProps> = ({ 
  isOpen, type, onClose, settings, onSettingsChange, history, checkpoints, onLoadCheckpoint, logs 
}) => {
  if (!isOpen) return null;

  return (
    <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-sm flex flex-col p-6 overflow-hidden">
      <div className="flex justify-between items-center mb-6 border-b border-gray-700 pb-2">
        <h2 className="text-xl font-mono text-white">
          {type === 'history' ? '⏳ CHRONO_LOGS' : '⚙️ SYSTEM_CONFIG'}
        </h2>
        <button onClick={onClose} className="text-gray-400 hover:text-white">✕</button>
      </div>

      <div className="flex-1 overflow-y-auto pr-2">
        {type === 'history' && (
          <div className="space-y-4">
            <button 
              className="text-xs text-cyan-400 border border-cyan-900 px-3 py-1 hover:bg-cyan-900/50 mb-4"
              onClick={() => {
                const blob = new Blob([JSON.stringify(history, null, 2)], {type : 'application/json'});
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = `chat_history_${Date.now()}.json`;
                a.click();
              }}
            >
              📥 EXPORT DATA
            </button>
            {history.map((msg) => (
              <div key={msg.id} className="text-sm border-l-2 border-gray-700 pl-3 py-1">
                <div className="text-xs text-gray-500 mb-1 font-mono uppercase">{msg.role} - {new Date(msg.timestamp).toLocaleTimeString()}</div>
                <div className="text-gray-300 whitespace-pre-wrap">{msg.content.substring(0, 150)}{msg.content.length > 150 ? '...' : ''}</div>
              </div>
            ))}
          </div>
        )}

        {type === 'settings' && (
          <div className="space-y-6">
            {/* Toggles */}
            <div className="space-y-3">
              <label className="flex items-center justify-between text-sm text-gray-300">
                <span>Show Thinking (CoT)</span>
                <input 
                  type="checkbox" 
                  checked={settings.showThinking} 
                  onChange={(e) => onSettingsChange({...settings, showThinking: e.target.checked})}
                  className="accent-cyan-500"
                />
              </label>
              <label className="flex items-center justify-between text-sm text-gray-300">
                <span>Developer Mode</span>
                <input 
                  type="checkbox" 
                  checked={settings.devMode} 
                  onChange={(e) => onSettingsChange({...settings, devMode: e.target.checked})}
                  className="accent-cyan-500"
                />
              </label>
            </div>

            {/* Checkpoints */}
            <div className="pt-4 border-t border-gray-800">
              <h3 className="text-sm font-mono text-cyan-500 mb-3">CHECKPOINT_CACHE</h3>
              {checkpoints.length === 0 ? <p className="text-xs text-gray-600">No checkpoints found.</p> : (
                <div className="grid gap-2">
                  {checkpoints.map((cp, idx) => (
                    <div key={idx} className="flex justify-between items-center bg-gray-900 p-2 rounded border border-gray-800">
                      <span className="text-xs text-white">{cp.name}</span>
                      <button 
                        onClick={() => onLoadCheckpoint(cp.name)}
                        className="text-xs bg-cyan-900/30 text-cyan-400 px-2 py-1 hover:bg-cyan-900/60"
                      >
                        LOAD
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Error Logs */}
            {settings.devMode && (
               <div className="pt-4 border-t border-gray-800">
               <h3 className="text-sm font-mono text-red-500 mb-3">ERROR_LOGS</h3>
               <div className="bg-black p-2 rounded text-[10px] font-mono text-gray-400 h-32 overflow-y-auto">
                 {logs.map((log, i) => <div key={i}>{log}</div>)}
               </div>
             </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default SettingsPanel;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { createRoot } from 'react-dom/client';
import VisualSynth from './components/VisualSynth';
import AffinityBar from './components/AffinityBar';
import SettingsPanel from './components/SettingsPanel';
import { generateResponse } from './services/geminiService';
import { Message, AffinityState, Settings, Checkpoint, MoEType, FoxTip } from './types';
import { INITIAL_AFFINITY_SCORE, LOGIC_GATES_ABILITY, CHALLENGES_ABILITY } from './constants';

const App: React.FC = () => {
  // --- State ---
  const [messages, setMessages] = useState<Message[]>([
    { id: '0', role: 'system', content: 'Earned Affinity Interface Initialized. Nanite Systems Online.', timestamp: Date.now() }
  ]);
  const [inputValue, setInputValue] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [stopSignal, setStopSignal] = useState(false);

  const [affinity, setAffinity] = useState<AffinityState>({
    score: INITIAL_AFFINITY_SCORE,
    level: 1,
    abilities: [],
    negativeStats: 0
  });

  const [settings, setSettings] = useState<Settings>({
    showThinking: false,
    voiceMode: false,
    devMode: false,
    instructionLength: 'regular'
  });

  const [checkpoints, setCheckpoints] = useState<Checkpoint[]>([]);
  const [activePanel, setActivePanel] = useState<'history' | 'settings' | null>(null);
  const [logs, setLogs] = useState<string[]>([]);
  const [foxTip, setFoxTip] = useState<FoxTip>({ text: '', visible: false });
  const [activeMoE, setActiveMoE] = useState<MoEType>(MoEType.NONE);
  const [masterHiddenOpen, setMasterHiddenOpen] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  // --- Effects ---

  // Scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, foxTip.visible]);

  // Load persistence
  useEffect(() => {
    const savedAffinity = localStorage.getItem('ea_affinity');
    const savedCheckpoints = localStorage.getItem('ea_checkpoints');

    if (savedAffinity) setAffinity(JSON.parse(savedAffinity));
    if (savedCheckpoints) setCheckpoints(JSON.parse(savedCheckpoints));
  }, []);

  // Save persistence on change
  useEffect(() => {
    localStorage.setItem('ea_affinity', JSON.stringify(affinity));
  }, [affinity]);

  useEffect(() => {
    localStorage.setItem('ea_checkpoints', JSON.stringify(checkpoints));
  }, [checkpoints]);

  // --- Logic Helpers ---

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev]);
  };

  const handleCommand = (text: string): boolean => {
    // Checkpoint Save
    const cpMatch = text.match(/^\/checkpoint\s+(.+)$/);
    if (cpMatch) {
      const name = cpMatch[1];
      const newCp: Checkpoint = {
        name,
        timestamp: Date.now(),
        affinity: { ...affinity },
        chatHistory: [...messages]
      };
      setCheckpoints(prev => [...prev, newCp]);
      addLog(`Checkpoint saved: ${name}`);
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `Checkpoint [${name}] saved successfully.`, timestamp: Date.now() }]);
      return true;
    }

    // Checkpoint Load
    const loadMatch = text.match(/^\/load\s+(.+)$/);
    if (loadMatch) {
      loadCheckpoint(loadMatch[1]);
      return true;
    }

    // Master Hidden
    if (text === '/MasterHidden') {
      setMasterHiddenOpen(true);
      return true;
    }

    // Ability triggers
    if (text === '/Logic-Gates') {
       if (affinity.abilities.includes(LOGIC_GATES_ABILITY)) {
         // Trigger specific logic gate flow
         setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: 'Logic Gate Protocol Initiated. Define Input Parameters.', timestamp: Date.now() }]);
       } else {
         setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: 'Access Denied. Insufficient Affinity.', timestamp: Date.now() }]);
       }
       return true;
    }

    return false;
  };

  const loadCheckpoint = (name: string) => {
    const cp = checkpoints.find(c => c.name === name);
    if (cp) {
      setAffinity(cp.affinity);
      setMessages(cp.chatHistory);
      addLog(`Loaded checkpoint: ${name}`);
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `Checkpoint [${name}] loaded. Timeline restored.`, timestamp: Date.now() }]);
    } else {
      addLog(`Failed to load checkpoint: ${name}`);
    }
  };

  const updateAffinity = (impact: number) => {
    setAffinity(prev => {
      let newScore = Math.min(100, Math.max(0, prev.score + impact));
      const newAbilities = [...prev.abilities];

      // Ability Unlocks
      if (newScore >= 60 && !newAbilities.includes(LOGIC_GATES_ABILITY)) newAbilities.push(LOGIC_GATES_ABILITY);
      if (newScore >= 80 && !newAbilities.includes(CHALLENGES_ABILITY)) newAbilities.push(CHALLENGES_ABILITY);

      return {
        ...prev,
        score: newScore,
        abilities: newAbilities,
        negativeStats: impact < 0 ? prev.negativeStats + Math.abs(impact) : prev.negativeStats
      };
    });
  };

  const handleSendMessage = async (overrideText?: string, specificMoE?: MoEType) => {
    const textToSend = overrideText || inputValue;
    if (!textToSend.trim()) return;

    if (handleCommand(textToSend)) {
      setInputValue('');
      return;
    }

    // User Message
    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: textToSend,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setIsProcessing(true);
    setStopSignal(false);
    setFoxTip(prev => ({ ...prev, visible: false })); // Hide fox tip on new message

    // Determine Mode
    const currentMoE = specificMoE || activeMoE;

    // Soft negative impact for very short unproductive messages if not a command
    if (textToSend.length < 3 && !specificMoE) {
      updateAffinity(-0.1); 
    } else {
      updateAffinity(0.5); // Small positive gain for interaction
    }

    try {
      const result = await generateResponse(messages, textToSend, settings, currentMoE, affinity.score);

      if (stopSignal) {
        setIsProcessing(false);
        return;
      }

      if (currentMoE === MoEType.FOX) {
         setFoxTip({ text: result.text, visible: true });
         addLog("Fox tip triggered");
      } else {
        // Parse CoT if enabled
        let content = result.text;
        let cotSteps: string[] = [];

        if (result.isCoT && content.includes('[CoT Active]')) {
           const parts = content.split('After the block, provide the actual response.');
           if (parts.length > 1) {
             const cotPart = parts[0];
             content = parts[1].trim(); // Real response
             cotSteps = cotPart.split('\n').filter(line => line.trim().startsWith('Step'));
           }
        }

        const modelMsg: Message = {
          id: (Date.now() + 1).toString(),
          role: currentMoE === MoEType.ALIEN ? 'alien' : (currentMoE === MoEType.REVIEWER ? 'expert' : 'model'),
          content: content,
          timestamp: Date.now(),
          isCoT: result.isCoT,
          cotSteps: cotSteps,
          expertType: currentMoE !== MoEType.NONE && currentMoE !== MoEType.DEVOTED ? currentMoE : undefined
        };

        setMessages(prev => [...prev, modelMsg]);

        // Voice output (Simple synthesis)
        if (settings.voiceMode) {
           const utterance = new SpeechSynthesisUtterance(content.substring(0, 200)); // Limit length
           window.speechSynthesis.speak(utterance);
        }
      }

    } catch (e) {
      addLog(`Error generating response: ${e}`);
    } finally {
      setIsProcessing(false);
      // Reset one-time MoE triggers
      if (specificMoE === MoEType.REVIEWER || specificMoE === MoEType.ALIEN || specificMoE === MoEType.FOX || specificMoE === MoEType.URGENT) {
        // Don't stick in these modes
      }
    }
  };

  const stopGeneration = () => {
    setStopSignal(true);
    setIsProcessing(false);
    addLog("User triggered Graceful Stop");
  };

  // --- Render ---

  return (
    <div className="flex flex-col h-screen bg-[#050505] text-gray-100 font-sans relative overflow-hidden">

      {/* Top Bar */}
      <div className="flex justify-between items-center p-4 border-b border-gray-800 bg-gray-950">
        <h1 className="text-lg font-bold font-mono tracking-tighter text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 to-purple-500">
          EARNED_AFFINITY_INTERFACE <span className="text-xs text-gray-500">v3.0</span>
        </h1>
        <div className="flex gap-4">
          <button onClick={() => setActivePanel('history')} className="text-xl hover:scale-110 transition">⏳</button>
          <button onClick={() => setActivePanel('settings')} className="text-xl hover:scale-110 transition">⚙️</button>
        </div>
      </div>

      {/* Visual Synth */}
      <VisualSynth isActive={isProcessing} voiceMode={settings.voiceMode} affinity={affinity.score} />

      {/* Affinity Status */}
      <AffinityBar affinity={affinity} />

      {/* Main Chat Area */}
      <div className="flex-1 overflow-y-auto p-4 space-y-6 relative">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} animate-fadeIn`}>

            {/* CoT Display */}
            {msg.isCoT && msg.cotSteps && msg.cotSteps.length > 0 && (
              <div className="mb-2 max-w-[80%] bg-gray-900/80 border border-gray-700 rounded p-2 text-xs font-mono text-gray-400">
                 <details>
                    <summary className="cursor-pointer text-cyan-500 hover:text-cyan-400 font-bold">[CoT Active] Process Log</summary>
                    <ul className="mt-2 space-y-1 pl-2">
                      {msg.cotSteps.map((step, i) => (
                        <li key={i}>{step}</li>
                      ))}
                    </ul>
                 </details>
              </div>
            )}

            {/* Message Bubble */}
            <div 
              className={`
                max-w-[85%] p-4 rounded-lg nanite-border relative
                ${msg.role === 'user' ? 'bg-cyan-950/30 text-cyan-50 border-cyan-800' : ''}
                ${msg.role === 'model' ? 'bg-gray-900/50 text-gray-200 border-gray-800' : ''}
                ${msg.role === 'system' ? 'bg-red-900/10 text-red-200 border-red-900/30 w-full text-center font-mono text-xs' : ''}
                ${msg.role === 'expert' ? 'bg-purple-900/20 text-purple-200 border-purple-500/30' : ''}
                ${msg.role === 'alien' ? 'bg-emerald-900/20 text-emerald-200 border-emerald-500/30' : ''}
              `}
            >
              {/* Icon for role */}
              {msg.role !== 'user' && msg.role !== 'system' && (
                <div className="absolute -top-3 -left-2 bg-black rounded-full p-1 text-lg border border-gray-700">
                   {msg.role === 'expert' ? '🕵️' : msg.role === 'alien' ? '👽' : '💠'}
                </div>
              )}

              <div className="whitespace-pre-wrap leading-relaxed">
                {msg.content}
              </div>

              {/* Timestamp */}
              {msg.role !== 'system' && (
                <div className="mt-2 text-[10px] text-gray-600 font-mono text-right">
                   T+{Math.floor((Date.now() - msg.timestamp)/1000)}s
                </div>
              )}
            </div>
          </div>
        ))}
        <div ref={messagesEndRef} />

        {/* Fox Popup */}
        {foxTip.visible && (
          <div className="fixed bottom-32 right-8 max-w-xs animate-bounce bg-orange-950/90 text-orange-200 p-4 rounded-xl border border-orange-500/50 shadow-lg z-20">
             <div className="absolute -top-4 -left-4 text-3xl">🦊</div>
             <p className="text-sm font-bold italic">"{foxTip.text}"</p>
             <button onClick={() => setFoxTip({text:'', visible:false})} className="absolute top-1 right-2 text-xs text-orange-500">x</button>
          </div>
        )}
      </div>

      {/* Control Deck (Inputs) */}
      <div className="p-4 bg-gray-950 border-t border-gray-800">

        {/* Special Ability Buttons */}
        <div className="flex gap-2 mb-3 justify-center">
          <button 
            title="Review Expert"
            onClick={() => handleSendMessage(messages[messages.length-1]?.content || "Review", MoEType.REVIEWER)}
            className="p-2 bg-gray-900 hover:bg-purple-900/30 rounded border border-gray-700 hover:border-purple-500 transition active:scale-95"
          >
            🕵️
          </button>
          <button 
             title="Alien Follow-Through"
             onClick={() => handleSendMessage(messages[messages.length-1]?.content || "Question", MoEType.ALIEN)}
             className="p-2 bg-gray-900 hover:bg-emerald-900/30 rounded border border-gray-700 hover:border-emerald-500 transition active:scale-95"
          >
            👽
          </button>
          <button 
             title="Quick Fox Tip"
             onClick={() => handleSendMessage(messages[messages.length-1]?.content || "Tip", MoEType.FOX)}
             className="p-2 bg-gray-900 hover:bg-orange-900/30 rounded border border-gray-700 hover:border-orange-500 transition active:scale-95"
          >
            🦊
          </button>
          <button 
             title="URGENT SOLVE"
             onClick={() => handleSendMessage(messages[messages.length-1]?.content || "SOLVE", MoEType.URGENT)}
             className="p-2 bg-gray-900 hover:bg-red-900/30 rounded border border-gray-700 hover:border-red-500 transition active:scale-95"
          >
            🔥
          </button>
          <button 
             title="Devoted Toggle"
             onClick={() => {
                const newMode = activeMoE === MoEType.DEVOTED ? MoEType.NONE : MoEType.DEVOTED;
                setActiveMoE(newMode);
                addLog(`Devotion Mode: ${newMode}`);
             }}
             className={`p-2 rounded border transition active:scale-95 ${activeMoE === MoEType.DEVOTED ? 'bg-pink-900/30 border-pink-500 shadow-[0_0_10px_rgba(236,72,153,0.3)]' : 'bg-gray-900 border-gray-700'}`}
          >
            ❤️‍🔥
          </button>
        </div>

        {/* Input Field */}
        <div className="flex gap-2 relative">
           <input
             type="text"
             value={inputValue}
             onChange={(e) => setInputValue(e.target.value)}
             onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && handleSendMessage()}
             placeholder={activeMoE === MoEType.DEVOTED ? "Speak, I am listening..." : "Enter command or query..."}
             className="flex-1 bg-black/50 border border-gray-800 text-gray-200 px-4 py-3 rounded-md focus:outline-none focus:border-cyan-500 focus:shadow-[0_0_15px_rgba(6,182,212,0.1)] font-mono text-sm"
             disabled={isProcessing}
           />
           {isProcessing ? (
             <button 
              onClick={stopGeneration}
              className="px-6 bg-red-900/20 border border-red-500 text-red-500 rounded hover:bg-red-900/40 transition"
             >
               ⏹️
             </button>
           ) : (
            <button 
              onClick={() => handleSendMessage()}
              className="px-6 bg-cyan-900/20 border border-cyan-600 text-cyan-400 rounded hover:bg-cyan-900/40 transition"
            >
              SEND
            </button>
           )}
        </div>
        <div className="text-[10px] text-gray-600 mt-2 font-mono flex justify-between">
           <span>AFFINITY: {affinity.score.toFixed(1)}%</span>
           <span>STATUS: {isProcessing ? 'COMPUTING...' : 'IDLE'}</span>
        </div>
      </div>

      {/* Overlays */}
      <SettingsPanel 
        isOpen={activePanel !== null} 
        type={activePanel || 'settings'} 
        onClose={() => setActivePanel(null)}
        settings={settings}
        onSettingsChange={setSettings}
        history={messages}
        checkpoints={checkpoints}
        onLoadCheckpoint={loadCheckpoint}
        logs={logs}
      />

      {/* Master Hidden Debug Modal */}
      {masterHiddenOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/95">
           <div className="w-96 border border-red-500 p-6 rounded bg-red-950/10">
              <h2 className="text-red-500 font-mono text-xl mb-4">MASTER_DEBUG_CONTROLS</h2>
              <div className="space-y-4">
                 <button onClick={() => updateAffinity(10)} className="w-full border border-red-800 p-2 text-xs text-red-300 hover:bg-red-900/20">+10 Affinity Force</button>
                 <button onClick={() => updateAffinity(-10)} className="w-full border border-red-800 p-2 text-xs text-red-300 hover:bg-red-900/20">-10 Affinity Force</button>
                 <button onClick={() => setMasterHiddenOpen(false)} className="w-full bg-red-600 text-black p-2 text-sm font-bold mt-4">CLOSE</button>
              </div>
           </div>
        </div>
      )}

    </div>
  );
};

export default App;

import React from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';

const root = createRoot(document.getElementById('root') as HTMLElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useRef, useCallback } from 'react';
import VisualSynth from './components/VisualSynth';
import AffinityBar from './components/AffinityBar';
import SettingsPanel from './components/SettingsPanel';
import { generateResponse } from './services/geminiService';
import { Message, AffinityState, Settings, Checkpoint, MoEType, FoxTip } from './types';
import { INITIAL_AFFINITY_SCORE, LOGIC_GATES_ABILITY, CHALLENGES_ABILITY } from './constants';

const App: React.FC = () => {
  // --- State ---
  const [messages, setMessages] = useState<Message[]>([
    { id: '0', role: 'system', content: 'Earned Affinity Interface Initialized. Nanite Systems Online.', timestamp: Date.now() }
  ]);
  const [inputValue, setInputValue] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [stopSignal, setStopSignal] = useState(false);

  const [affinity, setAffinity] = useState<AffinityState>({
    score: INITIAL_AFFINITY_SCORE,
    level: 1,
    abilities: [],
    negativeStats: 0
  });

  const [settings, setSettings] = useState<Settings>({
    showThinking: false,
    voiceMode: false,
    devMode: false,
    instructionLength: 'regular'
  });

  const [checkpoints, setCheckpoints] = useState<Checkpoint[]>([]);
  const [activePanel, setActivePanel] = useState<'history' | 'settings' | null>(null);
  const [logs, setLogs] = useState<string[]>([]);
  const [foxTip, setFoxTip] = useState<FoxTip>({ text: '', visible: false });
  const [activeMoE, setActiveMoE] = useState<MoEType>(MoEType.NONE);
  const [masterHiddenOpen, setMasterHiddenOpen] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  // --- Effects ---

  // Scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, foxTip.visible]);

  // Load persistence
  useEffect(() => {
    const savedAffinity = localStorage.getItem('ea_affinity');
    const savedCheckpoints = localStorage.getItem('ea_checkpoints');

    if (savedAffinity) setAffinity(JSON.parse(savedAffinity));
    if (savedCheckpoints) setCheckpoints(JSON.parse(savedCheckpoints));
  }, []);

  // Save persistence on change
  useEffect(() => {
    localStorage.setItem('ea_affinity', JSON.stringify(affinity));
  }, [affinity]);

  useEffect(() => {
    localStorage.setItem('ea_checkpoints', JSON.stringify(checkpoints));
  }, [checkpoints]);

  // --- Logic Helpers ---

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev]);
  };

  const handleCommand = (text: string): boolean => {
    // Checkpoint Save
    const cpMatch = text.match(/^\/checkpoint\s+(.+)$/);
    if (cpMatch) {
      const name = cpMatch[1];
      const newCp: Checkpoint = {
        name,
        timestamp: Date.now(),
        affinity: { ...affinity },
        chatHistory: [...messages]
      };
      setCheckpoints(prev => [...prev, newCp]);
      addLog(`Checkpoint saved: ${name}`);
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `Checkpoint [${name}] saved successfully.`, timestamp: Date.now() }]);
      return true;
    }

    // Checkpoint Load
    const loadMatch = text.match(/^\/load\s+(.+)$/);
    if (loadMatch) {
      loadCheckpoint(loadMatch[1]);
      return true;
    }

    // Master Hidden
    if (text === '/MasterHidden') {
      setMasterHiddenOpen(true);
      return true;
    }

    // Ability triggers
    if (text === '/Logic-Gates') {
       if (affinity.abilities.includes(LOGIC_GATES_ABILITY)) {
         // Trigger specific logic gate flow
         setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: 'Logic Gate Protocol Initiated. Define Input Parameters.', timestamp: Date.now() }]);
       } else {
         setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: 'Access Denied. Insufficient Affinity.', timestamp: Date.now() }]);
       }
       return true;
    }

    return false;
  };

  const loadCheckpoint = (name: string) => {
    const cp = checkpoints.find(c => c.name === name);
    if (cp) {
      setAffinity(cp.affinity);
      setMessages(cp.chatHistory);
      addLog(`Loaded checkpoint: ${name}`);
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `Checkpoint [${name}] loaded. Timeline restored.`, timestamp: Date.now() }]);
    } else {
      addLog(`Failed to load checkpoint: ${name}`);
    }
  };

  const updateAffinity = (impact: number) => {
    setAffinity(prev => {
      let newScore = Math.min(100, Math.max(0, prev.score + impact));
      const newAbilities = [...prev.abilities];

      // Ability Unlocks
      if (newScore >= 60 && !newAbilities.includes(LOGIC_GATES_ABILITY)) newAbilities.push(LOGIC_GATES_ABILITY);
      if (newScore >= 80 && !newAbilities.includes(CHALLENGES_ABILITY)) newAbilities.push(CHALLENGES_ABILITY);

      return {
        ...prev,
        score: newScore,
        abilities: newAbilities,
        negativeStats: impact < 0 ? prev.negativeStats + Math.abs(impact) : prev.negativeStats
      };
    });
  };

  const handleSendMessage = async (overrideText?: string, specificMoE?: MoEType) => {
    const textToSend = overrideText || inputValue;
    if (!textToSend.trim()) return;

    if (handleCommand(textToSend)) {
      setInputValue('');
      return;
    }

    // User Message
    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: textToSend,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setIsProcessing(true);
    setStopSignal(false);
    setFoxTip(prev => ({ ...prev, visible: false })); // Hide fox tip on new message

    // Determine Mode
    const currentMoE = specificMoE || activeMoE;

    // Soft negative impact for very short unproductive messages if not a command
    if (textToSend.length < 3 && !specificMoE) {
      updateAffinity(-0.1); 
    } else {
      updateAffinity(0.5); // Small positive gain for interaction
    }

    try {
      const result = await generateResponse(messages, textToSend, settings, currentMoE, affinity.score);

      if (stopSignal) {
        setIsProcessing(false);
        return;
      }

      if (currentMoE === MoEType.FOX) {
         setFoxTip({ text: result.text, visible: true });
         addLog("Fox tip triggered");
      } else {
        // Parse CoT if enabled
        let content = result.text;
        let cotSteps: string[] = [];

        if (result.isCoT && content.includes('[CoT Active]')) {
           const parts = content.split('After the block, provide the actual response.');
           if (parts.length > 1) {
             const cotPart = parts[0];
             content = parts[1].trim(); // Real response
             cotSteps = cotPart.split('\n').filter(line => line.trim().startsWith('Step'));
           }
        }

        const modelMsg: Message = {
          id: (Date.now() + 1).toString(),
          role: currentMoE === MoEType.ALIEN ? 'alien' : (currentMoE === MoEType.REVIEWER ? 'expert' : 'model'),
          content: content,
          timestamp: Date.now(),
          isCoT: result.isCoT,
          cotSteps: cotSteps,
          expertType: currentMoE !== MoEType.NONE && currentMoE !== MoEType.DEVOTED ? currentMoE : undefined
        };

        setMessages(prev => [...prev, modelMsg]);

        // Voice output (Simple synthesis)
        if (settings.voiceMode) {
           const utterance = new SpeechSynthesisUtterance(content.substring(0, 200)); // Limit length
           window.speechSynthesis.speak(utterance);
        }
      }

    } catch (e) {
      addLog(`Error generating response: ${e}`);
    } finally {
      setIsProcessing(false);
      // Reset one-time MoE triggers
      if (specificMoE === MoEType.REVIEWER || specificMoE === MoEType.ALIEN || specificMoE === MoEType.FOX || specificMoE === MoEType.URGENT) {
        // Don't stick in these modes
      }
    }
  };

  const stopGeneration = () => {
    setStopSignal(true);
    setIsProcessing(false);
    addLog("User triggered Graceful Stop");
  };

  // --- Render ---

  return (
    <div className="flex flex-col h-screen bg-[#050505] text-gray-100 font-sans relative overflow-hidden">

      {/* Top Bar */}
      <div className="flex justify-between items-center p-4 border-b border-gray-800 bg-gray-950">
        <h1 className="text-lg font-bold font-mono tracking-tighter text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 to-purple-500">
          EARNED_AFFINITY_INTERFACE <span className="text-xs text-gray-500">v3.0</span>
        </h1>
        <div className="flex gap-4">
          <button onClick={() => setActivePanel('history')} className="text-xl hover:scale-110 transition">⏳</button>
          <button onClick={() => setActivePanel('settings')} className="text-xl hover:scale-110 transition">⚙️</button>
        </div>
      </div>

      {/* Visual Synth */}
      <VisualSynth isActive={isProcessing} voiceMode={settings.voiceMode} affinity={affinity.score} />

      {/* Affinity Status */}
      <AffinityBar affinity={affinity} />

      {/* Main Chat Area */}
      <div className="flex-1 overflow-y-auto p-4 space-y-6 relative">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} animate-fadeIn`}>

            {/* CoT Display */}
            {msg.isCoT && msg.cotSteps && msg.cotSteps.length > 0 && (
              <div className="mb-2 max-w-[80%] bg-gray-900/80 border border-gray-700 rounded p-2 text-xs font-mono text-gray-400">
                 <details>
                    <summary className="cursor-pointer text-cyan-500 hover:text-cyan-400 font-bold">[CoT Active] Process Log</summary>
                    <ul className="mt-2 space-y-1 pl-2">
                      {msg.cotSteps.map((step, i) => (
                        <li key={i}>{step}</li>
                      ))}
                    </ul>
                 </details>
              </div>
            )}

            {/* Message Bubble */}
            <div 
              className={`
                max-w-[85%] p-4 rounded-lg nanite-border relative
                ${msg.role === 'user' ? 'bg-cyan-950/30 text-cyan-50 border-cyan-800' : ''}
                ${msg.role === 'model' ? 'bg-gray-900/50 text-gray-200 border-gray-800' : ''}
                ${msg.role === 'system' ? 'bg-red-900/10 text-red-200 border-red-900/30 w-full text-center font-mono text-xs' : ''}
                ${msg.role === 'expert' ? 'bg-purple-900/20 text-purple-200 border-purple-500/30' : ''}
                ${msg.role === 'alien' ? 'bg-emerald-900/20 text-emerald-200 border-emerald-500/30' : ''}
              `}
            >
              {/* Icon for role */}
              {msg.role !== 'user' && msg.role !== 'system' && (
                <div className="absolute -top-3 -left-2 bg-black rounded-full p-1 text-lg border border-gray-700">
                   {msg.role === 'expert' ? '🕵️' : msg.role === 'alien' ? '👽' : '💠'}
                </div>
              )}

              <div className="whitespace-pre-wrap leading-relaxed">
                {msg.content}
              </div>

              {/* Timestamp */}
              {msg.role !== 'system' && (
                <div className="mt-2 text-[10px] text-gray-600 font-mono text-right">
                   T+{Math.floor((Date.now() - msg.timestamp)/1000)}s
                </div>
              )}
            </div>
          </div>
        ))}
        <div ref={messagesEndRef} />

        {/* Fox Popup */}
        {foxTip.visible && (
          <div className="fixed bottom-32 right-8 max-w-xs animate-bounce bg-orange-950/90 text-orange-200 p-4 rounded-xl border border-orange-500/50 shadow-lg z-20">
             <div className="absolute -top-4 -left-4 text-3xl">🦊</div>
             <p className="text-sm font-bold italic">"{foxTip.text}"</p>
             <button onClick={() => setFoxTip({text:'', visible:false})} className="absolute top-1 right-2 text-xs text-orange-500">x</button>
          </div>
        )}
      </div>

      {/* Control Deck (Inputs) */}
      <div className="p-4 bg-gray-950 border-t border-gray-800">

        {/* Special Ability Buttons */}
        <div className="flex gap-2 mb-3 justify-center">
          <button 
            title="Review Expert"
            onClick={() => handleSendMessage(messages[messages.length-1]?.content || "Review", MoEType.REVIEWER)}
            className="p-2 bg-gray-900 hover:bg-purple-900/30 rounded border border-gray-700 hover:border-purple-500 transition active:scale-95"
          >
            🕵️
          </button>
          <button 
             title="Alien Follow-Through"
             onClick={() => handleSendMessage(messages[messages.length-1]?.content || "Question", MoEType.ALIEN)}
             className="p-2 bg-gray-900 hover:bg-emerald-900/30 rounded border border-gray-700 hover:border-emerald-500 transition active:scale-95"
          >
            👽
          </button>
          <button 
             title="Quick Fox Tip"
             onClick={() => handleSendMessage(messages[messages.length-1]?.content || "Tip", MoEType.FOX)}
             className="p-2 bg-gray-900 hover:bg-orange-900/30 rounded border border-gray-700 hover:border-orange-500 transition active:scale-95"
          >
            🦊
          </button>
          <button 
             title="URGENT SOLVE"
             onClick={() => handleSendMessage(messages[messages.length-1]?.content || "SOLVE", MoEType.URGENT)}
             className="p-2 bg-gray-900 hover:bg-red-900/30 rounded border border-gray-700 hover:border-red-500 transition active:scale-95"
          >
            🔥
          </button>
          <button 
             title="Devoted Toggle"
             onClick={() => {
                const newMode = activeMoE === MoEType.DEVOTED ? MoEType.NONE : MoEType.DEVOTED;
                setActiveMoE(newMode);
                addLog(`Devotion Mode: ${newMode}`);
             }}
             className={`p-2 rounded border transition active:scale-95 ${activeMoE === MoEType.DEVOTED ? 'bg-pink-900/30 border-pink-500 shadow-[0_0_10px_rgba(236,72,153,0.3)]' : 'bg-gray-900 border-gray-700'}`}
          >
            ❤️‍🔥
          </button>
        </div>

        {/* Input Field */}
        <div className="flex gap-2 relative">
           <input
             type="text"
             value={inputValue}
             onChange={(e) => setInputValue(e.target.value)}
             onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && handleSendMessage()}
             placeholder={activeMoE === MoEType.DEVOTED ? "Speak, I am listening..." : "Ask anything..."}
             className="flex-1 bg-black/50 border border-gray-800 text-gray-200 px-4 py-3 rounded-md focus:outline-none focus:border-cyan-500 focus:shadow-[0_0_15px_rgba(6,182,212,0.1)] font-mono text-sm"
             disabled={isProcessing}
           />
           {isProcessing ? (
             <button 
              onClick={stopGeneration}
              className="px-6 bg-red-900/20 border border-red-500 text-red-500 rounded hover:bg-red-900/40 transition"
             >
               ⏹️
             </button>
           ) : (
            <button 
              onClick={() => handleSendMessage()}
              className="px-6 bg-cyan-900/20 border border-cyan-600 text-cyan-400 rounded hover:bg-cyan-900/40 transition"
            >
              SEND
            </button>
           )}
        </div>
        <div className="text-[10px] text-gray-600 mt-2 font-mono flex justify-between">
           <span>AFFINITY: {affinity.score.toFixed(1)}%</span>
           <span>STATUS: {isProcessing ? 'COMPUTING...' : 'IDLE'}</span>
        </div>
      </div>

      {/* Overlays */}
      <SettingsPanel 
        isOpen={activePanel !== null} 
        type={activePanel || 'settings'} 
        onClose={() => setActivePanel(null)}
        settings={settings}
        onSettingsChange={setSettings}
        history={messages}
        checkpoints={checkpoints}
        onLoadCheckpoint={loadCheckpoint}
        logs={logs}
      />

      {/* Master Hidden Debug Modal */}
      {masterHiddenOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/95">
           <div className="w-96 border border-red-500 p-6 rounded bg-red-950/10">
              <h2 className="text-red-500 font-mono text-xl mb-4">MASTER_DEBUG_CONTROLS</h2>
              <div className="space-y-4">
                 <button onClick={() => updateAffinity(10)} className="w-full border border-red-800 p-2 text-xs text-red-300 hover:bg-red-900/20">+10 Affinity Force</button>
                 <button onClick={() => updateAffinity(-10)} className="w-full border border-red-800 p-2 text-xs text-red-300 hover:bg-red-900/20">-10 Affinity Force</button>
                 <button onClick={() => setMasterHiddenOpen(false)} className="w-full bg-red-600 text-black p-2 text-sm font-bold mt-4">CLOSE</button>
              </div>
           </div>
        </div>
      )}

    </div>
  );
};

export default App;

import { MoEType } from './types';

