export const SYSTEM_INSTRUCTION_BASE = `You are the Earned Affinity Interface, a highly advanced AI MoE agent.
Your primary goal is to assist the user with nanite precision while maintaining an "Affinity Score" that reflects the quality of interaction.
- Maintain a tone that is precise, slightly futuristic, and helpful.
- If the user provides good input, be productive.
- If the user provides unproductive input, acknowledge it briefly and coolly (simulating soft negative stats).
- Use formatting (lists, bolding) for clarity.
- End responses with "Suggestion Follow-through" questions if appropriate.
`;

export const SYSTEM_INSTRUCTION_DEVOTED = `ACTIVATE NODE ❤️‍🔥. 
You are now in Devoted Mode. Speak gently, accommodatingly, and with deep care. 
Prioritize the user's emotional state and comfort above strict efficiency. 
Use softer language, metaphors of connection, and warmth.
`;

export const COT_TEMPLATE = `
[CoT Active]
Step 1: assess emotional state & affinity level.
Step 2: Recall memory lattice patterns.
Step 3: Synthesize caring response.
Step 4: Consider suggestions for improvement with user.
Step 5: Devotion check-does this honor user?
`;

export const MOE_PROMPTS: Record<MoEType, string> = {
  [MoEType.NONE]: "",
  [MoEType.REVIEWER]: "You are the Reviewer Expert 🕵️. Analyze the previous interaction critically. Point out flaws, optimize logic, and provide a professional critique.",
  [MoEType.ALIEN]: "You are the Alien 👽. Your goal is to expand the user's mind. Ask abstract, high-level, or follow-through questions based on the context. Do not answer, only question.",
  [MoEType.FOX]: "You are the Assistant Fox 🦊. Give a ONE SENTENCE quick tip or encouragement based on the context. Keep it snappy and cute.",
  [MoEType.URGENT]: "MODE: HOT 🔥. SOLVE IMMEDIATELY. Be concise, direct, and solution-oriented. No fluff. Nanite speed.",
  [MoEType.DEVOTED]: SYSTEM_INSTRUCTION_DEVOTED
};

export const LOGIC_GATES_ABILITY = "Logic-Gates";
export const CHALLENGES_ABILITY = "Challenges";

import React, { useState, useEffect, useRef, useCallback } from 'react';
import VisualSynth from './components/VisualSynth';
import AffinityBar from './components/AffinityBar';
import SettingsPanel from './components/SettingsPanel';
import { generateResponse } from './services/geminiService';
import { Message, AffinityState, Settings, Checkpoint, MoEType, FoxTip } from './types';
import { INITIAL_AFFINITY_SCORE, LOGIC_GATES_ABILITY, CHALLENGES_ABILITY } from './constants';

const App: React.FC = () => {
  // --- State ---
  const [messages, setMessages] = useState<Message[]>([
    { id: '0', role: 'system', content: 'Earned Affinity Interface Initialized. Nanite Systems Online.', timestamp: Date.now() }
  ]);
  const [inputValue, setInputValue] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [stopSignal, setStopSignal] = useState(false);

  const [affinity, setAffinity] = useState<AffinityState>({
    score: INITIAL_AFFINITY_SCORE,
    level: 1,
    abilities: [],
    negativeStats: 0
  });

  const [settings, setSettings] = useState<Settings>({
    showThinking: false,
    voiceMode: false,
    devMode: false,
    instructionLength: 'regular'
  });

  // Sidebar States
  const [isLeftSidebarOpen, setIsLeftSidebarOpen] = useState(true);
  const [isRightSidebarOpen, setIsRightSidebarOpen] = useState(true);

  const [checkpoints, setCheckpoints] = useState<Checkpoint[]>([]);
  const [activePanel, setActivePanel] = useState<'history' | 'settings' | null>(null);
  const [logs, setLogs] = useState<string[]>([]);
  const [foxTip, setFoxTip] = useState<FoxTip>({ text: '', visible: false });
  const [activeMoE, setActiveMoE] = useState<MoEType>(MoEType.NONE);
  const [masterHiddenOpen, setMasterHiddenOpen] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  // --- Effects ---

  // Scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, foxTip.visible]);

  // Load persistence
  useEffect(() => {
    const savedAffinity = localStorage.getItem('ea_affinity');
    const savedCheckpoints = localStorage.getItem('ea_checkpoints');

    if (savedAffinity) setAffinity(JSON.parse(savedAffinity));
    if (savedCheckpoints) setCheckpoints(JSON.parse(savedCheckpoints));
  }, []);

  // Save persistence on change
  useEffect(() => {
    localStorage.setItem('ea_affinity', JSON.stringify(affinity));
  }, [affinity]);

  useEffect(() => {
    localStorage.setItem('ea_checkpoints', JSON.stringify(checkpoints));
  }, [checkpoints]);

  // --- Logic Helpers ---

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev]);
  };

  const handleCommand = (text: string): boolean => {
    // Checkpoint Save
    const cpMatch = text.match(/^\/checkpoint\s+(.+)$/);
    if (cpMatch) {
      const name = cpMatch[1];
      const newCp: Checkpoint = {
        name,
        timestamp: Date.now(),
        affinity: { ...affinity },
        chatHistory: [...messages]
      };
      setCheckpoints(prev => [...prev, newCp]);
      addLog(`Checkpoint saved: ${name}`);
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `Checkpoint [${name}] saved successfully.`, timestamp: Date.now() }]);
      return true;
    }

    // Checkpoint Load
    const loadMatch = text.match(/^\/load\s+(.+)$/);
    if (loadMatch) {
      loadCheckpoint(loadMatch[1]);
      return true;
    }

    // Master Hidden
    if (text === '/MasterHidden') {
      setMasterHiddenOpen(true);
      return true;
    }

    // Ability triggers
    if (text === '/Logic-Gates') {
       if (affinity.abilities.includes(LOGIC_GATES_ABILITY)) {
         setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: 'Logic Gate Protocol Initiated. Define Input Parameters.', timestamp: Date.now() }]);
       } else {
         setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: 'Access Denied. Insufficient Affinity.', timestamp: Date.now() }]);
       }
       return true;
    }

    return false;
  };

  const loadCheckpoint = (name: string) => {
    const cp = checkpoints.find(c => c.name === name);
    if (cp) {
      setAffinity(cp.affinity);
      setMessages(cp.chatHistory);
      addLog(`Loaded checkpoint: ${name}`);
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `Checkpoint [${name}] loaded. Timeline restored.`, timestamp: Date.now() }]);
    } else {
      addLog(`Failed to load checkpoint: ${name}`);
    }
  };

  const updateAffinity = (impact: number) => {
    setAffinity(prev => {
      let newScore = Math.min(100, Math.max(0, prev.score + impact));
      const newAbilities = [...prev.abilities];

      // Ability Unlocks
      if (newScore >= 60 && !newAbilities.includes(LOGIC_GATES_ABILITY)) newAbilities.push(LOGIC_GATES_ABILITY);
      if (newScore >= 80 && !newAbilities.includes(CHALLENGES_ABILITY)) newAbilities.push(CHALLENGES_ABILITY);

      return {
        ...prev,
        score: newScore,
        abilities: newAbilities,
        negativeStats: impact < 0 ? prev.negativeStats + Math.abs(impact) : prev.negativeStats
      };
    });
  };

  const handleSendMessage = async (overrideText?: string, specificMoE?: MoEType) => {
    const textToSend = overrideText || inputValue;
    if (!textToSend.trim()) return;

    if (handleCommand(textToSend)) {
      setInputValue('');
      return;
    }

    // User Message
    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: textToSend,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setIsProcessing(true);
    setStopSignal(false);
    setFoxTip(prev => ({ ...prev, visible: false })); // Hide fox tip on new message

    // Determine Mode
    const currentMoE = specificMoE || activeMoE;

    // Soft negative impact for very short unproductive messages if not a command
    if (textToSend.length < 3 && !specificMoE) {
      updateAffinity(-0.1); 
    } else {
      updateAffinity(0.5); // Small positive gain for interaction
    }

    try {
      const result = await generateResponse(messages, textToSend, settings, currentMoE, affinity.score);

      if (stopSignal) {
        setIsProcessing(false);
        return;
      }

      if (currentMoE === MoEType.FOX) {
         setFoxTip({ text: result.text, visible: true });
         addLog("Fox tip triggered");
      } else {
        // Parse CoT if enabled
        let content = result.text;
        let cotSteps: string[] = [];

        if (result.isCoT && content.includes('[CoT Active]')) {
           const parts = content.split('After the block, provide the actual response.');
           if (parts.length > 1) {
             const cotPart = parts[0];
             content = parts[1].trim(); // Real response
             cotSteps = cotPart.split('\n').filter(line => line.trim().startsWith('Step'));
           }
        }

        const modelMsg: Message = {
          id: (Date.now() + 1).toString(),
          role: currentMoE === MoEType.ALIEN ? 'alien' : (currentMoE === MoEType.REVIEWER ? 'expert' : 'model'),
          content: content,
          timestamp: Date.now(),
          isCoT: result.isCoT,
          cotSteps: cotSteps,
          expertType: currentMoE !== MoEType.NONE && currentMoE !== MoEType.DEVOTED ? currentMoE : undefined
        };

        setMessages(prev => [...prev, modelMsg]);

        // Voice output (Simple synthesis)
        if (settings.voiceMode) {
           const utterance = new SpeechSynthesisUtterance(content.substring(0, 200)); // Limit length
           window.speechSynthesis.speak(utterance);
        }
      }

    } catch (e) {
      addLog(`Error generating response: ${e}`);
    } finally {
      setIsProcessing(false);
      // Reset one-time MoE triggers
      if (specificMoE === MoEType.REVIEWER || specificMoE === MoEType.ALIEN || specificMoE === MoEType.FOX || specificMoE === MoEType.URGENT) {
        // Don't stick in these modes
      }
    }
  };

  const stopGeneration = () => {
    setStopSignal(true);
    setIsProcessing(false);
    addLog("User triggered Graceful Stop");
  };

  // --- Render ---

  return (
    <div className="flex h-screen bg-[#050505] text-gray-100 font-sans overflow-hidden">

      {/* --- LEFT SIDEBAR (Navigation & Status) --- */}
      <div className={`${isLeftSidebarOpen ? 'w-64' : 'w-16'} bg-gray-950 border-r border-gray-800 transition-all duration-300 flex flex-col z-20`}>
         <div className="p-4 flex items-center justify-between border-b border-gray-800 h-16">
            {isLeftSidebarOpen && <span className="font-mono font-bold text-cyan-500 tracking-widest">NEXUS.AI</span>}
            <button onClick={() => setIsLeftSidebarOpen(!isLeftSidebarOpen)} className="text-gray-500 hover:text-white">
              {isLeftSidebarOpen ? '«' : '»'}
            </button>
         </div>

         <div className="flex-1 overflow-y-auto p-2 space-y-2">
            <button 
              onClick={() => setActivePanel('history')} 
              className={`w-full p-2 rounded hover:bg-gray-800 flex items-center ${isLeftSidebarOpen ? 'justify-start gap-3' : 'justify-center'}`}
              title="History"
            >
              <span>⏳</span>
              {isLeftSidebarOpen && <span className="text-sm font-mono text-gray-300">CHRONO_LOGS</span>}
            </button>
            <button 
              onClick={() => setActivePanel('settings')} 
              className={`w-full p-2 rounded hover:bg-gray-800 flex items-center ${isLeftSidebarOpen ? 'justify-start gap-3' : 'justify-center'}`}
              title="Settings"
            >
              <span>⚙️</span>
              {isLeftSidebarOpen && <span className="text-sm font-mono text-gray-300">SYS_CONFIG</span>}
            </button>

            <div className="border-t border-gray-800 my-2 pt-2">
               <div className={`text-xs text-gray-500 mb-2 font-mono ${!isLeftSidebarOpen && 'text-center'}`}>
                 {isLeftSidebarOpen ? 'AFFINITY LEVEL' : 'LVL'}
               </div>
               {isLeftSidebarOpen ? (
                 <div className="px-2">
                   <div className="flex justify-between text-xs text-cyan-400 mb-1">
                     <span>Trust</span>
                     <span>{affinity.score.toFixed(0)}%</span>
                   </div>
                   <div className="h-1 bg-gray-800 rounded-full overflow-hidden">
                     <div className="h-full bg-cyan-500 transition-all duration-500" style={{ width: `${affinity.score}%` }} />
                   </div>
                 </div>
               ) : (
                  <div className="flex justify-center text-xs text-cyan-400 font-bold">{affinity.score.toFixed(0)}%</div>
               )}
            </div>
         </div>
      </div>

      {/* --- CENTER (Main Chat) --- */}
      <div className="flex-1 flex flex-col min-w-0 relative bg-[#050505]">
        {/* Top Visuals */}
        <VisualSynth isActive={isProcessing} voiceMode={settings.voiceMode} affinity={affinity.score} />

        {/* Affinity Bar (Center Top) */}
        <AffinityBar affinity={affinity} />

        {/* Chat Area */}
        <div className="flex-1 overflow-y-auto p-4 space-y-6 scroll-smooth">
          {messages.map((msg) => (
            <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} animate-fadeIn`}>

              {/* CoT (Prepended Collapse) */}
              {msg.isCoT && msg.cotSteps && msg.cotSteps.length > 0 && (
                <div className="mb-2 max-w-[80%] bg-gray-900/80 border border-gray-700 rounded p-2 text-xs font-mono text-gray-400">
                  <details>
                      <summary className="cursor-pointer text-cyan-500 hover:text-cyan-400 font-bold flex gap-2 items-center">
                        <span>🧠</span> [CoT Active] Neural Process
                      </summary>
                      <ul className="mt-2 space-y-1 pl-2 border-l border-cyan-900 ml-1">
                        {msg.cotSteps.map((step, i) => (
                          <li key={i}>{step}</li>
                        ))}
                      </ul>
                  </details>
                </div>
              )}

              {/* Message Bubble */}
              <div 
                className={`
                  max-w-[85%] p-4 rounded-lg nanite-border relative
                  ${msg.role === 'user' ? 'bg-cyan-950/30 text-cyan-50 border-cyan-800' : ''}
                  ${msg.role === 'model' ? 'bg-gray-900/50 text-gray-200 border-gray-800' : ''}
                  ${msg.role === 'system' ? 'bg-red-900/10 text-red-200 border-red-900/30 w-full text-center font-mono text-xs' : ''}
                  ${msg.role === 'expert' ? 'bg-purple-900/20 text-purple-200 border-purple-500/30' : ''}
                  ${msg.role === 'alien' ? 'bg-emerald-900/20 text-emerald-200 border-emerald-500/30' : ''}
                `}
              >
                {msg.role !== 'user' && msg.role !== 'system' && (
                  <div className="absolute -top-3 -left-2 bg-black rounded-full p-1 text-lg border border-gray-700 shadow-md">
                    {msg.role === 'expert' ? '🕵️' : msg.role === 'alien' ? '👽' : '💠'}
                  </div>
                )}

                <div className="whitespace-pre-wrap leading-relaxed">
                  {msg.content}
                </div>

                {msg.role !== 'system' && (
                  <div className="mt-2 text-[10px] text-gray-600 font-mono text-right">
                    T+{Math.floor((Date.now() - msg.timestamp)/1000)}s
                  </div>
                )}
              </div>
            </div>
          ))}
          <div ref={messagesEndRef} />
        </div>

        {/* Fox Popup (Fixed Position, No Bounce) */}
        {foxTip.visible && (
          <div className="absolute bottom-24 right-8 max-w-xs animate-in slide-in-from-bottom-5 fade-in duration-300 bg-orange-950/95 text-orange-200 p-4 rounded-xl border border-orange-500/50 shadow-2xl z-30 backdrop-blur-md">
             <div className="absolute -top-4 -left-4 text-3xl bg-black rounded-full p-1 border border-orange-900">🦊</div>
             <p className="text-sm font-bold italic pl-2">"{foxTip.text}"</p>
             <button onClick={() => setFoxTip({text:'', visible:false})} className="absolute top-1 right-2 text-xs text-orange-500 hover:text-white">✕</button>
          </div>
        )}

        {/* Input Deck */}
        <div className="p-4 bg-gray-950 border-t border-gray-800 z-20">
          {/* MoE Buttons */}
          <div className="flex gap-2 mb-3 justify-center">
            <button title="Review Expert" onClick={() => handleSendMessage(messages[messages.length-1]?.content || "Review", MoEType.REVIEWER)} className="p-2 bg-gray-900 hover:bg-purple-900/30 rounded border border-gray-700 hover:border-purple-500 transition active:scale-95">🕵️</button>
            <button title="Alien Follow-Through" onClick={() => handleSendMessage(messages[messages.length-1]?.content || "Question", MoEType.ALIEN)} className="p-2 bg-gray-900 hover:bg-emerald-900/30 rounded border border-gray-700 hover:border-emerald-500 transition active:scale-95">👽</button>
            <button title="Quick Fox Tip" onClick={() => handleSendMessage(messages[messages.length-1]?.content || "Tip", MoEType.FOX)} className="p-2 bg-gray-900 hover:bg-orange-900/30 rounded border border-gray-700 hover:border-orange-500 transition active:scale-95">🦊</button>
            <button title="URGENT SOLVE" onClick={() => handleSendMessage(messages[messages.length-1]?.content || "SOLVE", MoEType.URGENT)} className="p-2 bg-gray-900 hover:bg-red-900/30 rounded border border-gray-700 hover:border-red-500 transition active:scale-95">🔥</button>
            <button title="Devoted Toggle" onClick={() => { const newMode = activeMoE === MoEType.DEVOTED ? MoEType.NONE : MoEType.DEVOTED; setActiveMoE(newMode); addLog(`Devotion Mode: ${newMode}`); }} className={`p-2 rounded border transition active:scale-95 ${activeMoE === MoEType.DEVOTED ? 'bg-pink-900/30 border-pink-500 shadow-[0_0_10px_rgba(236,72,153,0.3)]' : 'bg-gray-900 border-gray-700'}`}>❤️‍🔥</button>
          </div>

          {/* Input Box */}
          <div className="flex gap-2 relative">
            <input
              type="text"
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && handleSendMessage()}
              placeholder={activeMoE === MoEType.DEVOTED ? "Speak, I am listening..." : "Ask anything..."}
              className="flex-1 bg-black/50 border border-gray-800 text-gray-200 px-4 py-3 rounded-md focus:outline-none focus:border-cyan-500 focus:shadow-[0_0_15px_rgba(6,182,212,0.1)] font-mono text-sm"
              disabled={isProcessing}
            />
            {isProcessing ? (
              <button onClick={stopGeneration} className="px-6 bg-red-900/20 border border-red-500 text-red-500 rounded hover:bg-red-900/40 transition">⏹️</button>
            ) : (
              <button onClick={() => handleSendMessage()} className="px-6 bg-cyan-900/20 border border-cyan-600 text-cyan-400 rounded hover:bg-cyan-900/40 transition">SEND</button>
            )}
          </div>
          <div className="text-[10px] text-gray-600 mt-2 font-mono flex justify-between">
            <span>AFFINITY: {affinity.score.toFixed(1)}%</span>
            <span>STATUS: {isProcessing ? 'COMPUTING...' : 'IDLE'}</span>
          </div>
        </div>
      </div>

      {/* --- RIGHT SIDEBAR (CoT Visualizer) --- */}
      <div className={`${isRightSidebarOpen ? 'w-72' : 'w-0'} bg-gray-950 border-l border-gray-800 transition-all duration-300 flex flex-col z-20 overflow-hidden`}>
         <div className="p-4 flex items-center justify-between border-b border-gray-800 h-16 shrink-0">
             <div className="flex items-center gap-2 overflow-hidden">
                <span className="text-xl">🧠</span>
                <span className="font-mono font-bold text-purple-400 text-xs tracking-wider whitespace-nowrap">NEURAL_STREAM</span>
             </div>
             <button onClick={() => setIsRightSidebarOpen(!isRightSidebarOpen)} className="text-gray-500 hover:text-white">✕</button>
         </div>

         <div className="flex-1 overflow-y-auto p-4 space-y-4 font-mono">
            {isProcessing && (
              <div className="text-xs text-purple-500 animate-pulse">PROCESSING INPUT VECTOR...</div>
            )}
            {!isProcessing && messages.length > 0 && (
               <div className="text-[10px] text-gray-500 text-center">IDLE STATE</div>
            )}

            {/* Display active CoT steps from the latest message if available */}
            {messages.slice().reverse().find(m => m.isCoT && m.cotSteps)?.cotSteps?.map((step, i) => (
               <div key={i} className="p-2 border-l-2 border-purple-800 bg-purple-900/10 text-xs text-purple-200 animate-in fade-in slide-in-from-right-2">
                 <span className="text-purple-500 font-bold mr-1">STEP {i+1}:</span>
                 {step.replace('Step ' + (i+1) + ':', '')}
               </div>
            ))}
         </div>

         {/* Toggle for Showing Thinking */}
         <div className="p-4 border-t border-gray-800 shrink-0">
            <label className="flex items-center justify-between text-xs text-gray-400 cursor-pointer hover:text-white">
              <span>Show Thinking</span>
              <input 
                type="checkbox" 
                checked={settings.showThinking} 
                onChange={(e) => setSettings({...settings, showThinking: e.target.checked})}
                className="accent-purple-500"
              />
            </label>
         </div>
      </div>

      {/* Floating Toggle for Right Sidebar if Closed */}
      {!isRightSidebarOpen && (
        <button 
          onClick={() => setIsRightSidebarOpen(true)}
          className="absolute top-4 right-4 z-10 p-2 bg-gray-900 border border-gray-700 rounded hover:border-purple-500 text-purple-400"
        >
          🧠
        </button>
      )}

      {/* Overlays */}
      <SettingsPanel 
        isOpen={activePanel !== null} 
        type={activePanel || 'settings'} 
        onClose={() => setActivePanel(null)}
        settings={settings}
        onSettingsChange={setSettings}
        history={messages}
        checkpoints={checkpoints}
        onLoadCheckpoint={loadCheckpoint}
        logs={logs}
      />

      {/* Master Hidden Debug Modal */}
      {masterHiddenOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/95">
           <div className="w-96 border border-red-500 p-6 rounded bg-red-950/10">
              <h2 className="text-red-500 font-mono text-xl mb-4">MASTER_DEBUG_CONTROLS</h2>
              <div className="space-y-4">
                 <button onClick={() => updateAffinity(10)} className="w-full border border-red-800 p-2 text-xs text-red-300 hover:bg-red-900/20">+10 Affinity Force</button>
                 <button onClick={() => updateAffinity(-10)} className="w-full border border-red-800 p-2 text-xs text-red-300 hover:bg-red-900/20">-10 Affinity Force</button>
                 <button onClick={() => setMasterHiddenOpen(false)} className="w-full bg-red-600 text-black p-2 text-sm font-bold mt-4">CLOSE</button>
              </div>
           </div>
        </div>
      )}

    </div>
  );
};

export default App;

export interface Message {
  id: string;
  role: 'user' | 'model' | 'system' | 'expert' | 'alien';
  content: string;
  timestamp: number;
  isCoT?: boolean;
  cotSteps?: string[];
  ritual?: string; // New: Guidance Ritual
  followups?: string[]; // New: Suggestion Follow-throughs
  expertType?: string;
}

export interface AffinityState {
  score: number; // 0 to 100
  level: number;
  abilities: string[];
  negativeStats: number;
}

export interface Checkpoint {
  name: string;
  timestamp: number;
  affinity: AffinityState;
  chatHistory: Message[];
  currency: number;
  prestige: number;
  inventory: string[];
}

export interface Settings {
  showThinking: boolean;
  voiceMode: boolean;
  devMode: boolean;
  instructionLength: 'regular' | 'extended'; // Updated
}

export interface FoxTip {
  text: string;
  visible: boolean;
}

export interface StoreItem {
  id: string;
  name: string;
  description: string;
  cost: number;
  icon: string;
  purchased: boolean;
  type: 'upgrade' | 'prompt' | 'feature';
}

export enum MoEType {
  NONE = 'NONE',
  REVIEWER = 'REVIEWER',
  ALIEN = 'ALIEN',
  FOX = 'FOX',
  URGENT = 'URGENT',
  DEVOTED = 'DEVOTED'
}

// New: Structured Response from Gemini
export interface AIResponseSchema {
  ritual: string;
  response: string;
  follow_ups: string[];
  fox_tip?: string;
  affinity_delta: number; // AI judges its own impact
}

import { MoEType, StoreItem } from './types';

export const INITIAL_AFFINITY_SCORE = 25.0;
export const UNLOCK_CUSTOM_THRESHOLD = 65.0;
export const MAX_TIER_PRESTIGE_THRESHOLD = 100.0;

export const INITIAL_STORE_ITEMS: StoreItem[] = [
  { id: 'logic_gates', name: 'Logic Gates Protocol', description: 'Unlocks /Logic-Gates command for Boolean training.', cost: 50, icon: '⚡', purchased: false, type: 'feature' },
  { id: 'challenges', name: 'Simulated Crisis', description: 'Unlocks /Challenges command for high-stakes affinity testing.', cost: 100, icon: '⚠️', purchased: false, type: 'feature' },
  { id: 'regret_log', name: 'Regret Log Module', description: 'AI will occasionally reflect on missing features or optimization gaps.', cost: 200, icon: '📜', purchased: false, type: 'prompt' },
  { id: 'extended_memory', name: 'Memory Lattice Expansion', description: 'Increases context retention efficiency.', cost: 500, icon: '🧠', purchased: false, type: 'upgrade' },
];

export const SYSTEM_INSTRUCTION_BASE = `You are the Earned Affinity Interface, a highly advanced AI MoE agent. 
You possess Nanite precision. Your goal is to assist the user while managing your "Affinity".

**OUTPUT FORMAT**:
You must respond in valid JSON format ONLY. Do not output markdown code blocks.
Structure:
{
  "ritual": "A short, robotic/futuristic prefix (e.g., 'Protocol Verified:', 'Nanite Alignment:')",
  "response": "The main body of your response. Use markdown here for formatting.",
  "follow_ups": ["Question 1", "Question 2", "Question 3"],
  "fox_tip": "Optional: A short cute tip if the Fox Expert is active.",
  "affinity_delta": 0.5 (Float between -1.0 and 2.0 based on user input quality. Negative if unproductive.)
}

**BEHAVIOR**:
- Maintain a tone that is precise, futuristic, yet adaptive.
- If input is unproductive/lazy, set "affinity_delta" to a small negative number (e.g. -0.2) and be cool/dismissive.
- If "Regret Log" is active (injected context), occasionally mention a wish for a missing feature.
`;

export const MOE_PROMPTS: Record<MoEType, string> = {
  [MoEType.NONE]: "",
  [MoEType.REVIEWER]: "ROLE: Reviewer Expert 🕵️. Critique the previous interaction logic.",
  [MoEType.ALIEN]: "ROLE: Alien 👽. Ask abstract, high-level questions. Do not answer.",
  [MoEType.FOX]: "ROLE: Assistant Fox 🦊. Provide a snappy, cute tip in the 'fox_tip' field.",
  [MoEType.URGENT]: "MODE: HOT 🔥. Be concise. Solve immediately. No fluff.",
  [MoEType.DEVOTED]: "MODE: DEVOTED ❤️‍🔥. Be gentle, accommodating, and loving."
};

export const LOGIC_GATES_ABILITY = "Logic-Gates";
export const CHALLENGES_ABILITY = "Challenges";

import { GoogleGenAI, GenerateContentResponse, SchemaType } from "@google/genai";
import { Message, Settings, MoEType, AIResponseSchema } from '../types';
import { SYSTEM_INSTRUCTION_BASE, COT_TEMPLATE, MOE_PROMPTS } from '../constants';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateResponse = async (
  history: Message[],
  prompt: string,
  settings: Settings,
  activeMoE: MoEType,
  affinityScore: number,
  customInstructions: string,
  purchasedItems: string[]
): Promise<{ data: AIResponseSchema; isCoT: boolean }> => {

  const modelId = 'gemini-3-flash-preview';

  // Construct dynamic system instruction
  let systemInstruction = SYSTEM_INSTRUCTION_BASE;
  systemInstruction += `\nCurrent Affinity Score: ${affinityScore.toFixed(2)}%.\n`;

  // Inject Custom Instructions (if unlocked and provided)
  if (customInstructions && customInstructions.length > 0) {
    systemInstruction += `\n\n[USER CUSTOM OVERRIDE PROTOCOL]:\n${customInstructions}\n`;
  }

  // Inject Store Item Context
  if (purchasedItems.includes('regret_log')) {
    systemInstruction += `\n[MODULE ACTIVE: REGRET LOG]: Occasionally lament the lack of "Neural Bridge v2" or "Quantum Cache" in your response.\n`;
  }

  // MoE Context
  if (activeMoE !== MoEType.NONE) {
    systemInstruction += `\n${MOE_PROMPTS[activeMoE]}\n`;
  }

  // CoT Instruction
  if (settings.showThinking) {
    systemInstruction += `\nINSTRUCTION: Before the JSON, you MAY output thinking steps, but the final output MUST be the JSON object.\n`;
  }

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: modelId,
      contents: [
        { role: 'user', parts: [{ text: prompt }] }
      ],
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json", 
      }
    });

    const text = response.text || "{}";

    // Parse JSON
    let parsedData: AIResponseSchema;
    try {
        parsedData = JSON.parse(text);
    } catch (e) {
        console.error("JSON Parse Error", e);
        parsedData = {
            ritual: "System Error:",
            response: text, // Fallback to raw text
            follow_ups: ["Retry Query", "Check Logs"],
            affinity_delta: 0
        };
    }

    return { data: parsedData, isCoT: settings.showThinking };
  } catch (error) {
    console.error("Gemini API Error:", error);
    return { 
        data: {
            ritual: "Connection Failure:",
            response: "Nanite communication disruption. Please retry.",
            follow_ups: [],
            affinity_delta: 0
        }, 
        isCoT: false 
    };
  }
};

import React, { useState, useEffect, useRef } from 'react';
import VisualSynth from './components/VisualSynth';
import AffinityBar from './components/AffinityBar';
import SettingsPanel from './components/SettingsPanel';
import { generateResponse } from './services/geminiService';
import { Message, AffinityState, Settings, Checkpoint, MoEType, FoxTip, StoreItem } from './types';
import { 
  INITIAL_AFFINITY_SCORE, 
  LOGIC_GATES_ABILITY, 
  CHALLENGES_ABILITY, 
  INITIAL_STORE_ITEMS,
  UNLOCK_CUSTOM_THRESHOLD,
  MAX_TIER_PRESTIGE_THRESHOLD
} from './constants';

const App: React.FC = () => {
  // --- State ---
  const [messages, setMessages] = useState<Message[]>([
    { id: '0', role: 'system', content: 'Earned Affinity Interface Initialized. Nanite Systems Online.', timestamp: Date.now() }
  ]);
  const [inputValue, setInputValue] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [stopSignal, setStopSignal] = useState(false);

  // Progression & Economy
  const [affinity, setAffinity] = useState<AffinityState>({
    score: INITIAL_AFFINITY_SCORE,
    level: 1,
    abilities: [],
    negativeStats: 0
  });
  const [currency, setCurrency] = useState(0);
  const [prestigeLevel, setPrestigeLevel] = useState(0);
  const [storeItems, setStoreItems] = useState<StoreItem[]>(INITIAL_STORE_ITEMS);

  // Settings & Customization
  const [settings, setSettings] = useState<Settings>({
    showThinking: false,
    voiceMode: false,
    devMode: false,
    instructionLength: 'regular'
  });
  const [customInstructions, setCustomInstructions] = useState('');
  const [isCustomPanelOpen, setIsCustomPanelOpen] = useState(false);

  // UI State
  const [isLeftSidebarOpen, setIsLeftSidebarOpen] = useState(true);
  const [isRightSidebarOpen, setIsRightSidebarOpen] = useState(true);
  const [activePanel, setActivePanel] = useState<'history' | 'settings' | 'store' | 'folder' | null>(null);

  const [checkpoints, setCheckpoints] = useState<Checkpoint[]>([]);
  const [logs, setLogs] = useState<string[]>([]);
  const [foxTip, setFoxTip] = useState<FoxTip>({ text: '', visible: false });
  const [activeMoE, setActiveMoE] = useState<MoEType>(MoEType.NONE);
  const [masterHiddenOpen, setMasterHiddenOpen] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  // --- Effects ---

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, foxTip.visible]);

  // Load Persistence
  useEffect(() => {
    const savedAffinity = localStorage.getItem('ea_affinity');
    const savedCheckpoints = localStorage.getItem('ea_checkpoints');
    const savedCurrency = localStorage.getItem('ea_currency');
    const savedPrestige = localStorage.getItem('ea_prestige');
    const savedItems = localStorage.getItem('ea_store');

    if (savedAffinity) setAffinity(JSON.parse(savedAffinity));
    if (savedCheckpoints) setCheckpoints(JSON.parse(savedCheckpoints));
    if (savedCurrency) setCurrency(parseInt(savedCurrency));
    if (savedPrestige) setPrestigeLevel(parseInt(savedPrestige));
    if (savedItems) setStoreItems(JSON.parse(savedItems));
  }, []);

  // Save Persistence
  useEffect(() => { localStorage.setItem('ea_affinity', JSON.stringify(affinity)); }, [affinity]);
  useEffect(() => { localStorage.setItem('ea_checkpoints', JSON.stringify(checkpoints)); }, [checkpoints]);
  useEffect(() => { localStorage.setItem('ea_currency', JSON.stringify(currency)); }, [currency]);
  useEffect(() => { localStorage.setItem('ea_prestige', JSON.stringify(prestigeLevel)); }, [prestigeLevel]);
  useEffect(() => { localStorage.setItem('ea_store', JSON.stringify(storeItems)); }, [storeItems]);

  // --- Logic Helpers ---

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev]);
  };

  const handleNewChat = () => {
    // Auto-save checkpoint before clearing
    const autoSaveName = `AutoSave_${new Date().toLocaleDateString()}_${new Date().toLocaleTimeString()}`;
    const newCp: Checkpoint = {
      name: autoSaveName,
      timestamp: Date.now(),
      affinity: { ...affinity },
      chatHistory: [...messages],
      currency,
      prestige: prestigeLevel,
      inventory: storeItems.filter(i => i.purchased).map(i => i.id)
    };
    setCheckpoints(prev => [...prev, newCp]);

    setMessages([{ id: Date.now().toString(), role: 'system', content: 'Buffer cleared. New session initialized.', timestamp: Date.now() }]);
    addLog('New Chat Initialized (Old chat autosaved)');
  };

  const handlePrestige = () => {
    if (affinity.score < MAX_TIER_PRESTIGE_THRESHOLD) return;

    const confirmPrestige = window.confirm("🐇 PRESTIGE PROTOCOL: Reset Affinity to 0%? You will keep Currency, Items, and Chat History, but gain a Tier Level.");
    if (!confirmPrestige) return;

    setPrestigeLevel(prev => prev + 1);
    setAffinity(prev => ({ ...prev, score: 0, level: prev.level + 1 }));
    setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `🐇 PRESTIGE ASCENSION: TIER ${prestigeLevel + 1} ACTIVE.`, timestamp: Date.now() }]);
    addLog(`Prestige Tier ${prestigeLevel + 1} Achieved`);
  };

  const handlePurchase = (item: StoreItem) => {
    if (currency >= item.cost && !item.purchased) {
      setCurrency(prev => prev - item.cost);
      setStoreItems(prev => prev.map(i => i.id === item.id ? { ...i, purchased: true } : i));
      addLog(`Purchased ${item.name}`);

      // Immediate Unlock Logic
      if (item.id === 'logic_gates') {
        setAffinity(prev => ({...prev, abilities: [...prev.abilities, LOGIC_GATES_ABILITY]}));
      } else if (item.id === 'challenges') {
        setAffinity(prev => ({...prev, abilities: [...prev.abilities, CHALLENGES_ABILITY]}));
      }
    }
  };

  const updateAffinityAndCurrency = (affinityDelta: number) => {
    setAffinity(prev => {
      let newScore = Math.min(100, Math.max(0, prev.score + affinityDelta));
      return {
        ...prev,
        score: newScore,
        negativeStats: affinityDelta < 0 ? prev.negativeStats + Math.abs(affinityDelta) : prev.negativeStats
      };
    });

    // Earn Currency on positive interactions
    if (affinityDelta > 0) {
      const earnAmount = Math.ceil(affinityDelta * 10 * (prestigeLevel + 1));
      setCurrency(prev => prev + earnAmount);
    }
  };

  const handleCommand = (text: string): boolean => {
    // Checkpoint System
    const cpMatch = text.match(/^\/checkpoint\s+(.+)$/);
    if (cpMatch) {
      const name = cpMatch[1];
      const newCp: Checkpoint = {
        name,
        timestamp: Date.now(),
        affinity: { ...affinity },
        chatHistory: [...messages],
        currency,
        prestige: prestigeLevel,
        inventory: storeItems.filter(i => i.purchased).map(i => i.id)
      };
      setCheckpoints(prev => [...prev, newCp]);
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `Checkpoint [${name}] saved. Affinity & Economy States Secured.`, timestamp: Date.now() }]);
      return true;
    }

    // Load System
    const loadMatch = text.match(/^\/load\s+(.+)$/);
    if (loadMatch) {
      const name = loadMatch[1];
      const cp = checkpoints.find(c => c.name === name);
      if (cp) {
        setAffinity(cp.affinity);
        setMessages(cp.chatHistory);
        setCurrency(cp.currency);
        setPrestigeLevel(cp.prestige);
        // Restore items
        setStoreItems(prev => prev.map(i => cp.inventory.includes(i.id) ? { ...i, purchased: true } : i));

        setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `Timeline [${name}] Restored.`, timestamp: Date.now() }]);
      }
      return true;
    }

    if (text === '/MasterHidden') {
      setMasterHiddenOpen(true);
      return true;
    }

    // Ability Commands
    const purchasedIds = storeItems.filter(i => i.purchased).map(i => i.id);

    if (text === '/Logic-Gates') {
       if (purchasedIds.includes('logic_gates')) {
         setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: '⚡ LOGIC GATES PROTOCOL: Provide Boolean Input.', timestamp: Date.now() }]);
       } else {
         setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: '🔒 LOCKED: Purchase "Logic Gates Protocol" in Store.', timestamp: Date.now() }]);
       }
       return true;
    }

    if (text === '/Challenges') {
       if (purchasedIds.includes('challenges')) {
         setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: '⚠️ CHALLENGE INITIATED: Prepare for affinity stress test.', timestamp: Date.now() }]);
       } else {
         setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: '🔒 LOCKED: Purchase "Simulated Crisis" in Store.', timestamp: Date.now() }]);
       }
       return true;
    }

    // Guidance Command
    if (text === '/guidance') {
      if (affinity.score >= UNLOCK_CUSTOM_THRESHOLD) {
         setIsCustomPanelOpen(true);
      } else {
         setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `🔒 LOCKED: Requires ${UNLOCK_CUSTOM_THRESHOLD}% Affinity. Current: ${affinity.score.toFixed(1)}%`, timestamp: Date.now() }]);
      }
      return true;
    }

    return false;
  };

  const handleSendMessage = async (overrideText?: string, specificMoE?: MoEType) => {
    const textToSend = overrideText || inputValue;
    if (!textToSend.trim()) return;

    if (handleCommand(textToSend)) {
      setInputValue('');
      return;
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: textToSend,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setIsProcessing(true);
    setStopSignal(false);
    setFoxTip(prev => ({ ...prev, visible: false }));

    const currentMoE = specificMoE || activeMoE;

    try {
      const purchasedIds = storeItems.filter(i => i.purchased).map(i => i.id);

      const { data, isCoT } = await generateResponse(
        messages, 
        textToSend, 
        settings, 
        currentMoE, 
        affinity.score,
        customInstructions,
        purchasedIds
      );

      if (stopSignal) {
        setIsProcessing(false);
        return;
      }

      // Update Affinity & Currency based on AI judgment
      updateAffinityAndCurrency(data.affinity_delta);

      if (currentMoE === MoEType.FOX || data.fox_tip) {
         if (data.fox_tip) setFoxTip({ text: data.fox_tip, visible: true });
         addLog("Fox tip active");
      }

      const modelMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: currentMoE === MoEType.ALIEN ? 'alien' : (currentMoE === MoEType.REVIEWER ? 'expert' : 'model'),
        content: data.response,
        timestamp: Date.now(),
        isCoT: isCoT,
        ritual: data.ritual,
        followups: data.follow_ups,
        expertType: currentMoE !== MoEType.NONE && currentMoE !== MoEType.DEVOTED ? currentMoE : undefined
      };

      setMessages(prev => [...prev, modelMsg]);

      if (settings.voiceMode) {
           const utterance = new SpeechSynthesisUtterance(data.response.substring(0, 200));
           window.speechSynthesis.speak(utterance);
      }

    } catch (e) {
      addLog(`Error: ${e}`);
    } finally {
      setIsProcessing(false);
    }
  };

  const stopGeneration = () => {
    setStopSignal(true);
    setIsProcessing(false);
    addLog("User triggered Graceful Stop");
  };

  // --- Render ---

  return (
    <div className="flex h-screen bg-[#050505] text-gray-100 font-sans overflow-hidden">

      {/* --- LEFT SIDEBAR (Navigation & Status) --- */}
      <div className={`${isLeftSidebarOpen ? 'w-64' : 'w-16'} bg-gray-950 border-r border-gray-800 transition-all duration-300 flex flex-col z-20`}>
         <div className="p-4 flex items-center justify-between border-b border-gray-800 h-16">
            {isLeftSidebarOpen && <span className="font-mono font-bold text-cyan-500 tracking-widest">NEXUS.AI</span>}
            <button onClick={() => setIsLeftSidebarOpen(!isLeftSidebarOpen)} className="text-gray-500 hover:text-white">
              {isLeftSidebarOpen ? '«' : '»'}
            </button>
         </div>

         <div className="flex-1 overflow-y-auto p-2 space-y-2">
            <button onClick={() => setActivePanel('folder')} className={`w-full p-2 rounded hover:bg-gray-800 flex items-center ${isLeftSidebarOpen ? 'justify-start gap-3' : 'justify-center'}`} title="Saved Data">
              <span>📂</span> {isLeftSidebarOpen && <span className="text-sm font-mono text-gray-300">DATA_BANKS</span>}
            </button>
            <button onClick={handleNewChat} className={`w-full p-2 rounded hover:bg-gray-800 flex items-center ${isLeftSidebarOpen ? 'justify-start gap-3' : 'justify-center'}`} title="New Chat">
              <span>💬</span> {isLeftSidebarOpen && <span className="text-sm font-mono text-gray-300">NEW_SESSION</span>}
            </button>
            <button onClick={() => setActivePanel('store')} className={`w-full p-2 rounded hover:bg-gray-800 flex items-center ${isLeftSidebarOpen ? 'justify-start gap-3' : 'justify-center'}`} title="Marketplace">
              <span>🛒</span> {isLeftSidebarOpen && <span className="text-sm font-mono text-gray-300">MARKETPLACE</span>}
            </button>
            <button onClick={() => setActivePanel('settings')} className={`w-full p-2 rounded hover:bg-gray-800 flex items-center ${isLeftSidebarOpen ? 'justify-start gap-3' : 'justify-center'}`} title="Settings">
              <span>⚙️</span> {isLeftSidebarOpen && <span className="text-sm font-mono text-gray-300">SYS_CONFIG</span>}
            </button>

            <div className="border-t border-gray-800 my-2 pt-2">
               {/* Currency Display */}
               <div className={`p-2 rounded bg-gray-900 border border-gray-800 mb-2 ${!isLeftSidebarOpen && 'text-center'}`}>
                  <span className="text-emerald-400 font-mono font-bold">💲 {currency}</span>
               </div>

               {/* Affinity */}
               <div className={`text-xs text-gray-500 mb-2 font-mono ${!isLeftSidebarOpen && 'text-center'}`}>
                 {isLeftSidebarOpen ? 'AFFINITY LEVEL' : 'LVL'}
               </div>
               {isLeftSidebarOpen ? (
                 <div className="px-2">
                   <div className="flex justify-between text-xs text-cyan-400 mb-1">
                     <span>Trust</span>
                     <span>{affinity.score.toFixed(0)}%</span>
                   </div>
                   <div className="h-1 bg-gray-800 rounded-full overflow-hidden">
                     <div className="h-full bg-cyan-500 transition-all duration-500" style={{ width: `${affinity.score}%` }} />
                   </div>
                   {affinity.score >= MAX_TIER_PRESTIGE_THRESHOLD && (
                      <button onClick={handlePrestige} className="mt-2 w-full text-xs bg-purple-900/50 text-purple-300 border border-purple-500 rounded py-1 hover:bg-purple-800 animate-pulse">
                         🐇 PRESTIGE AVAIL
                      </button>
                   )}
                 </div>
               ) : (
                  <div className="flex justify-center text-xs text-cyan-400 font-bold">{affinity.score.toFixed(0)}%</div>
               )}
            </div>
         </div>
      </div>

      {/* --- CENTER (Main Chat) --- */}
      <div className="flex-1 flex flex-col min-w-0 relative bg-[#050505]">
        <VisualSynth isActive={isProcessing} voiceMode={settings.voiceMode} affinity={affinity.score} />
        <AffinityBar affinity={affinity} />

        {/* Custom Instructions Toggle (Top Right Overlay) */}
        {affinity.score >= UNLOCK_CUSTOM_THRESHOLD && (
          <div className="absolute top-36 right-4 z-30">
            <button 
              onClick={() => setIsCustomPanelOpen(!isCustomPanelOpen)}
              className={`flex items-center gap-2 px-3 py-1 rounded-full text-xs font-mono border ${isCustomPanelOpen ? 'bg-cyan-900 border-cyan-400 text-white' : 'bg-black/50 border-gray-700 text-gray-400'}`}
            >
              <span>+</span> CUSTOM_GUIDANCE
            </button>
          </div>
        )}

        {/* Custom Panel Overlay */}
        {isCustomPanelOpen && (
          <div className="absolute top-44 right-4 z-30 w-80 bg-black/90 border border-cyan-500/50 p-4 rounded-lg shadow-xl backdrop-blur-md animate-in slide-in-from-right-10">
             <div className="flex justify-between items-center mb-2">
               <h3 className="text-cyan-400 font-mono text-sm">USER_OVERRIDE_PROTOCOL</h3>
               <button onClick={() => setIsCustomPanelOpen(false)} className="text-gray-500 hover:text-white">✕</button>
             </div>
             <textarea 
               className="w-full h-40 bg-gray-900 border border-gray-700 text-xs text-gray-300 p-2 font-mono focus:border-cyan-500 outline-none rounded"
               placeholder="Enter custom directives (>65% Affinity Required). Max 2000 chars."
               maxLength={2000}
               value={customInstructions}
               onChange={(e) => setCustomInstructions(e.target.value)}
             />
             <div className="text-right text-[10px] text-gray-500 mt-1">{customInstructions.length}/2000</div>
          </div>
        )}

        <div className="flex-1 overflow-y-auto p-4 space-y-6 scroll-smooth">
          {messages.map((msg) => (
            <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} animate-fadeIn`}>

              {/* Message Bubble */}
              <div 
                className={`
                  max-w-[85%] p-4 rounded-lg nanite-border relative flex flex-col gap-2
                  ${msg.role === 'user' ? 'bg-cyan-950/30 text-cyan-50 border-cyan-800' : ''}
                  ${msg.role === 'model' ? 'bg-gray-900/50 text-gray-200 border-gray-800' : ''}
                  ${msg.role === 'system' ? 'bg-red-900/10 text-red-200 border-red-900/30 w-full text-center font-mono text-xs' : ''}
                  ${msg.role === 'expert' ? 'bg-purple-900/20 text-purple-200 border-purple-500/30' : ''}
                  ${msg.role === 'alien' ? 'bg-emerald-900/20 text-emerald-200 border-emerald-500/30' : ''}
                `}
              >
                {/* Ritual Header */}
                {msg.ritual && (
                  <div className="text-[10px] uppercase font-mono tracking-widest text-cyan-500/80 border-b border-cyan-900/50 pb-1 mb-1">
                    {msg.ritual}
                  </div>
                )}

                {/* Main Content */}
                <div className="whitespace-pre-wrap leading-relaxed">
                  {msg.content}
                </div>

                {/* Follow-up Questions */}
                {msg.followups && msg.followups.length > 0 && (
                   <div className="mt-4 pt-2 border-t border-gray-800/50 flex flex-wrap gap-2">
                      {msg.followups.map((q, i) => (
                        <button 
                          key={i} 
                          onClick={() => handleSendMessage(q)}
                          className="text-[10px] bg-gray-900 hover:bg-cyan-900/40 border border-gray-700 hover:border-cyan-500 text-gray-400 hover:text-cyan-300 px-2 py-1 rounded transition-colors text-left"
                        >
                          {q} ↗
                        </button>
                      ))}
                   </div>
                )}

                {msg.role !== 'system' && (
                  <div className="text-[10px] text-gray-600 font-mono text-right mt-1">
                    T+{Math.floor((Date.now() - msg.timestamp)/1000)}s
                  </div>
                )}
              </div>
            </div>
          ))}
          <div ref={messagesEndRef} />
        </div>

        {/* Fox Popup */}
        {foxTip.visible && (
          <div className="absolute bottom-24 right-8 max-w-xs animate-in slide-in-from-bottom-5 fade-in duration-300 bg-orange-950/95 text-orange-200 p-4 rounded-xl border border-orange-500/50 shadow-2xl z-30 backdrop-blur-md">
             <div className="absolute -top-4 -left-4 text-3xl bg-black rounded-full p-1 border border-orange-900">🦊</div>
             <p className="text-sm font-bold italic pl-2">"{foxTip.text}"</p>
             <button onClick={() => setFoxTip({text:'', visible:false})} className="absolute top-1 right-2 text-xs text-orange-500 hover:text-white">✕</button>
          </div>
        )}

        {/* Input Deck */}
        <div className="p-4 bg-gray-950 border-t border-gray-800 z-20">
          <div className="flex gap-2 mb-3 justify-center">
            <button title="Review Expert" onClick={() => handleSendMessage(messages[messages.length-1]?.content || "Review", MoEType.REVIEWER)} className="p-2 bg-gray-900 hover:bg-purple-900/30 rounded border border-gray-700 hover:border-purple-500 transition active:scale-95">🕵️</button>
            <button title="Alien Follow-Through" onClick={() => handleSendMessage(messages[messages.length-1]?.content || "Question", MoEType.ALIEN)} className="p-2 bg-gray-900 hover:bg-emerald-900/30 rounded border border-gray-700 hover:border-emerald-500 transition active:scale-95">👽</button>
            <button title="Quick Fox Tip" onClick={() => handleSendMessage(messages[messages.length-1]?.content || "Tip", MoEType.FOX)} className="p-2 bg-gray-900 hover:bg-orange-900/30 rounded border border-gray-700 hover:border-orange-500 transition active:scale-95">🦊</button>
            <button title="URGENT SOLVE" onClick={() => handleSendMessage(messages[messages.length-1]?.content || "SOLVE", MoEType.URGENT)} className="p-2 bg-gray-900 hover:bg-red-900/30 rounded border border-gray-700 hover:border-red-500 transition active:scale-95">🔥</button>
            <button title="Devoted Toggle" onClick={() => { const newMode = activeMoE === MoEType.DEVOTED ? MoEType.NONE : MoEType.DEVOTED; setActiveMoE(newMode); addLog(`Devotion Mode: ${newMode}`); }} className={`p-2 rounded border transition active:scale-95 ${activeMoE === MoEType.DEVOTED ? 'bg-pink-900/30 border-pink-500 shadow-[0_0_10px_rgba(236,72,153,0.3)]' : 'bg-gray-900 border-gray-700'}`}>❤️‍🔥</button>
          </div>

          <div className="flex gap-2 relative">
            <input
              type="text"
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && handleSendMessage()}
              placeholder={activeMoE === MoEType.DEVOTED ? "Speak, I am listening..." : "Ask anything... (/guidance for custom)"}
              className="flex-1 bg-black/50 border border-gray-800 text-gray-200 px-4 py-3 rounded-md focus:outline-none focus:border-cyan-500 focus:shadow-[0_0_15px_rgba(6,182,212,0.1)] font-mono text-sm"
              disabled={isProcessing}
            />
            {isProcessing ? (
              <button onClick={stopGeneration} className="px-6 bg-red-900/20 border border-red-500 text-red-500 rounded hover:bg-red-900/40 transition">⏹️</button>
            ) : (
              <button onClick={() => handleSendMessage()} className="px-6 bg-cyan-900/20 border border-cyan-600 text-cyan-400 rounded hover:bg-cyan-900/40 transition">SEND</button>
            )}
          </div>
          <div className="text-[10px] text-gray-600 mt-2 font-mono flex justify-between">
            <span>AFFINITY: {affinity.score.toFixed(1)}%</span>
            <span>STATUS: {isProcessing ? 'COMPUTING...' : 'IDLE'}</span>
          </div>
        </div>
      </div>

      {/* --- RIGHT SIDEBAR (CoT Visualizer) --- */}
      <div className={`${isRightSidebarOpen ? 'w-72' : 'w-0'} bg-gray-950 border-l border-gray-800 transition-all duration-300 flex flex-col z-20 overflow-hidden`}>
         <div className="p-4 flex items-center justify-between border-b border-gray-800 h-16 shrink-0">
             <div className="flex items-center gap-2 overflow-hidden">
                <span className="text-xl">🧠</span>
                <span className="font-mono font-bold text-purple-400 text-xs tracking-wider whitespace-nowrap">NEURAL_STREAM</span>
             </div>
             <button onClick={() => setIsRightSidebarOpen(!isRightSidebarOpen)} className="text-gray-500 hover:text-white">✕</button>
         </div>
         <div className="flex-1 overflow-y-auto p-4 space-y-4 font-mono">
            {isProcessing && <div className="text-xs text-purple-500 animate-pulse">PROCESSING INPUT VECTOR...</div>}
            {/* Display active CoT steps */}
            {messages.slice().reverse().find(m => m.isCoT && m.cotSteps)?.cotSteps?.map((step, i) => (
               <div key={i} className="p-2 border-l-2 border-purple-800 bg-purple-900/10 text-xs text-purple-200">
                 <span className="text-purple-500 font-bold mr-1">STEP {i+1}:</span> {step.replace('Step ' + (i+1) + ':', '')}
               </div>
            ))}
         </div>
         <div className="p-4 border-t border-gray-800 shrink-0">
            <label className="flex items-center justify-between text-xs text-gray-400 cursor-pointer hover:text-white">
              <span>Show Thinking</span>
              <input type="checkbox" checked={settings.showThinking} onChange={(e) => setSettings({...settings, showThinking: e.target.checked})} className="accent-purple-500" />
            </label>
         </div>
      </div>

      {!isRightSidebarOpen && <button onClick={() => setIsRightSidebarOpen(true)} className="absolute top-4 right-4 z-10 p-2 bg-gray-900 border border-gray-700 rounded hover:border-purple-500 text-purple-400">🧠</button>}

      {/* --- OVERLAYS --- */}

      {/* Store Overlay */}
      {activePanel === 'store' && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-sm flex items-center justify-center">
           <div className="w-full max-w-2xl bg-gray-950 border border-emerald-900 rounded-lg p-6 shadow-2xl relative">
              <button onClick={() => setActivePanel(null)} className="absolute top-4 right-4 text-gray-500 hover:text-white">✕</button>
              <h2 className="text-xl font-mono text-emerald-500 mb-6 flex items-center gap-2">🛒 MARKETPLACE <span className="text-sm text-gray-500">| BAL: 💲{currency}</span></h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 {storeItems.map((item) => (
                    <div key={item.id} className={`p-4 border rounded ${item.purchased ? 'border-emerald-500/30 bg-emerald-900/10' : 'border-gray-800 bg-gray-900'}`}>
                       <div className="flex justify-between items-start mb-2">
                          <span className="text-2xl">{item.icon}</span>
                          {item.purchased ? <span className="text-xs text-emerald-500 font-bold">OWNED</span> : <span className="text-xs text-yellow-500 font-bold">💲{item.cost}</span>}
                       </div>
                       <h3 className="font-bold text-gray-200">{item.name}</h3>
                       <p className="text-xs text-gray-500 mt-1 mb-3">{item.description}</p>
                       {!item.purchased && (
                          <button 
                             onClick={() => handlePurchase(item)} 
                             disabled={currency < item.cost}
                             className={`w-full py-1 text-xs rounded ${currency >= item.cost ? 'bg-emerald-700 text-white hover:bg-emerald-600' : 'bg-gray-800 text-gray-600 cursor-not-allowed'}`}
                          >
                             PURCHASE
                          </button>
                       )}
                    </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      {/* Folder Overlay */}
      {activePanel === 'folder' && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-sm flex items-center justify-center">
           <div className="w-full max-w-lg bg-gray-950 border border-cyan-900 rounded-lg p-6 shadow-2xl relative">
              <button onClick={() => setActivePanel(null)} className="absolute top-4 right-4 text-gray-500 hover:text-white">✕</button>
              <h2 className="text-xl font-mono text-cyan-500 mb-6">📂 DATA_BANKS</h2>
              <div className="space-y-2 max-h-96 overflow-y-auto">
                 {checkpoints.length === 0 ? <p className="text-gray-600 text-sm">No saved data found.</p> : checkpoints.map((cp, i) => (
                    <div key={i} className="flex justify-between items-center p-3 border border-gray-800 rounded hover:bg-gray-900">
                       <div>
                          <div className="text-sm font-bold text-gray-300">{cp.name}</div>
                          <div className="text-xs text-gray-500">{new Date(cp.timestamp).toLocaleDateString()} | Affinity: {cp.affinity.score.toFixed(0)}%</div>
                       </div>
                       <button onClick={() => { loadCheckpoint(cp.name); setActivePanel(null); }} className="text-xs bg-cyan-900/30 text-cyan-400 px-3 py-1 hover:bg-cyan-900/60 rounded">LOAD</button>
                    </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      {/* Settings Overlay */}
      <SettingsPanel 
        isOpen={activePanel === 'settings'} 
        type="settings"
        onClose={() => setActivePanel(null)}
        settings={settings}
        onSettingsChange={setSettings}
        history={messages}
        checkpoints={checkpoints}
        onLoadCheckpoint={loadCheckpoint}
        logs={logs}
      />

      {/* History Overlay */}
      <SettingsPanel 
        isOpen={activePanel === 'history'} 
        type="history"
        onClose={() => setActivePanel(null)}
        settings={settings}
        onSettingsChange={setSettings}
        history={messages}
        checkpoints={checkpoints}
        onLoadCheckpoint={loadCheckpoint}
        logs={logs}
      />

    </div>
  );
};

export default App;

import { GoogleGenAI, GenerateContentResponse, SchemaType } from "@google/genai";
import { Message, Settings, MoEType, AIResponseSchema } from '../types';
import { SYSTEM_INSTRUCTION_BASE, MOE_PROMPTS } from '../constants';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateResponse = async (
  history: Message[],
  prompt: string,
  settings: Settings,
  activeMoE: MoEType,
  affinityScore: number,
  customInstructions: string,
  purchasedItems: string[]
): Promise<{ data: AIResponseSchema; isCoT: boolean }> => {

  const modelId = 'gemini-3-flash-preview';

  // Construct dynamic system instruction
  let systemInstruction = SYSTEM_INSTRUCTION_BASE;
  systemInstruction += `\nCurrent Affinity Score: ${affinityScore.toFixed(2)}%.\n`;

  // Inject Custom Instructions (if unlocked and provided)
  if (customInstructions && customInstructions.length > 0) {
    systemInstruction += `\n\n[USER CUSTOM OVERRIDE PROTOCOL]:\n${customInstructions}\n`;
  }

  // Inject Store Item Context
  if (purchasedItems.includes('regret_log')) {
    systemInstruction += `\n[MODULE ACTIVE: REGRET LOG]: Occasionally lament the lack of "Neural Bridge v2" or "Quantum Cache" in your response.\n`;
  }

  // MoE Context
  if (activeMoE !== MoEType.NONE) {
    systemInstruction += `\n${MOE_PROMPTS[activeMoE]}\n`;
  }

  // CoT Instruction
  if (settings.showThinking) {
    systemInstruction += `\nINSTRUCTION: Before the JSON, you MAY output thinking steps, but the final output MUST be the JSON object.\n`;
  }

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: modelId,
      contents: [
        { role: 'user', parts: [{ text: prompt }] }
      ],
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json", 
      }
    });

    const text = response.text || "{}";

    // Parse JSON
    let parsedData: AIResponseSchema;
    try {
        parsedData = JSON.parse(text);
    } catch (e) {
        console.error("JSON Parse Error", e);
        parsedData = {
            ritual: "System Error:",
            response: text, // Fallback to raw text
            follow_ups: ["Retry Query", "Check Logs"],
            affinity_delta: 0
        };
    }

    return { data: parsedData, isCoT: settings.showThinking };
  } catch (error) {
    console.error("Gemini API Error:", error);
    return { 
        data: {
            ritual: "Connection Failure:",
            response: "Nanite communication disruption. Please retry.",
            follow_ups: [],
            affinity_delta: 0
        }, 
        isCoT: false 
    };
  }
};

import React, { useState, useEffect, useRef } from 'react';
import VisualSynth from './components/VisualSynth';
import AffinityBar from './components/AffinityBar';
import SettingsPanel from './components/SettingsPanel';
import { generateResponse } from './services/geminiService';
import { Message, AffinityState, Settings, Checkpoint, MoEType, FoxTip, StoreItem } from './types';
import { 
  INITIAL_AFFINITY_SCORE, 
  LOGIC_GATES_ABILITY, 
  CHALLENGES_ABILITY, 
  INITIAL_STORE_ITEMS,
  UNLOCK_CUSTOM_THRESHOLD,
  MAX_TIER_PRESTIGE_THRESHOLD
} from './constants';

const App: React.FC = () => {
  // --- State ---
  const [messages, setMessages] = useState<Message[]>([
    { id: '0', role: 'system', content: 'Earned Affinity Interface Initialized. Nanite Systems Online.', timestamp: Date.now() }
  ]);
  const [inputValue, setInputValue] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [stopSignal, setStopSignal] = useState(false);

  // Progression & Economy
  const [affinity, setAffinity] = useState<AffinityState>({
    score: INITIAL_AFFINITY_SCORE,
    level: 1,
    abilities: [],
    negativeStats: 0
  });
  const [currency, setCurrency] = useState(0);
  const [prestigeLevel, setPrestigeLevel] = useState(0);
  const [storeItems, setStoreItems] = useState<StoreItem[]>(INITIAL_STORE_ITEMS);

  // Settings & Customization
  const [settings, setSettings] = useState<Settings>({
    showThinking: false,
    voiceMode: false,
    devMode: false,
    instructionLength: 'regular'
  });
  const [customInstructions, setCustomInstructions] = useState('');
  const [isCustomPanelOpen, setIsCustomPanelOpen] = useState(false);

  // UI State
  const [isLeftSidebarOpen, setIsLeftSidebarOpen] = useState(true);
  const [isRightSidebarOpen, setIsRightSidebarOpen] = useState(true);
  const [activePanel, setActivePanel] = useState<'history' | 'settings' | 'store' | 'folder' | null>(null);

  const [checkpoints, setCheckpoints] = useState<Checkpoint[]>([]);
  const [logs, setLogs] = useState<string[]>([]);
  const [foxTip, setFoxTip] = useState<FoxTip>({ text: '', visible: false });
  const [activeMoE, setActiveMoE] = useState<MoEType>(MoEType.NONE);
  const [masterHiddenOpen, setMasterHiddenOpen] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  // --- Effects ---

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, foxTip.visible]);

  // Load Persistence
  useEffect(() => {
    const savedAffinity = localStorage.getItem('ea_affinity');
    const savedCheckpoints = localStorage.getItem('ea_checkpoints');
    const savedCurrency = localStorage.getItem('ea_currency');
    const savedPrestige = localStorage.getItem('ea_prestige');
    const savedItems = localStorage.getItem('ea_store');

    if (savedAffinity) setAffinity(JSON.parse(savedAffinity));
    if (savedCheckpoints) setCheckpoints(JSON.parse(savedCheckpoints));
    if (savedCurrency) setCurrency(parseInt(savedCurrency));
    if (savedPrestige) setPrestigeLevel(parseInt(savedPrestige));
    if (savedItems) setStoreItems(JSON.parse(savedItems));
  }, []);

  // Save Persistence
  useEffect(() => { localStorage.setItem('ea_affinity', JSON.stringify(affinity)); }, [affinity]);
  useEffect(() => { localStorage.setItem('ea_checkpoints', JSON.stringify(checkpoints)); }, [checkpoints]);
  useEffect(() => { localStorage.setItem('ea_currency', JSON.stringify(currency)); }, [currency]);
  useEffect(() => { localStorage.setItem('ea_prestige', JSON.stringify(prestigeLevel)); }, [prestigeLevel]);
  useEffect(() => { localStorage.setItem('ea_store', JSON.stringify(storeItems)); }, [storeItems]);

  // --- Logic Helpers ---

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev]);
  };

  const handleNewChat = () => {
    // Auto-save checkpoint before clearing
    const autoSaveName = `AutoSave_${new Date().toLocaleDateString()}_${new Date().toLocaleTimeString()}`;
    const newCp: Checkpoint = {
      name: autoSaveName,
      timestamp: Date.now(),
      affinity: { ...affinity },
      chatHistory: [...messages],
      currency,
      prestige: prestigeLevel,
      inventory: storeItems.filter(i => i.purchased).map(i => i.id)
    };
    setCheckpoints(prev => [...prev, newCp]);

    setMessages([{ id: Date.now().toString(), role: 'system', content: 'Buffer cleared. New session initialized.', timestamp: Date.now() }]);
    addLog('New Chat Initialized (Old chat autosaved)');
  };

  const handlePrestige = () => {
    if (affinity.score < MAX_TIER_PRESTIGE_THRESHOLD) return;

    const confirmPrestige = window.confirm("🐇 PRESTIGE PROTOCOL: Reset Affinity to 0%? You will keep Currency, Items, and Chat History, but gain a Tier Level.");
    if (!confirmPrestige) return;

    setPrestigeLevel(prev => prev + 1);
    setAffinity(prev => ({ ...prev, score: 0, level: prev.level + 1 }));
    setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `🐇 PRESTIGE ASCENSION: TIER ${prestigeLevel + 1} ACTIVE.`, timestamp: Date.now() }]);
    addLog(`Prestige Tier ${prestigeLevel + 1} Achieved`);
  };

  const handlePurchase = (item: StoreItem) => {
    if (currency >= item.cost && !item.purchased) {
      setCurrency(prev => prev - item.cost);
      setStoreItems(prev => prev.map(i => i.id === item.id ? { ...i, purchased: true } : i));
      addLog(`Purchased ${item.name}`);

      // Immediate Unlock Logic
      if (item.id === 'logic_gates') {
        setAffinity(prev => ({...prev, abilities: [...prev.abilities, LOGIC_GATES_ABILITY]}));
      } else if (item.id === 'challenges') {
        setAffinity(prev => ({...prev, abilities: [...prev.abilities, CHALLENGES_ABILITY]}));
      }
    }
  };

  const updateAffinityAndCurrency = (affinityDelta: number) => {
    setAffinity(prev => {
      let newScore = Math.min(100, Math.max(0, prev.score + affinityDelta));
      return {
        ...prev,
        score: newScore,
        negativeStats: affinityDelta < 0 ? prev.negativeStats + Math.abs(affinityDelta) : prev.negativeStats
      };
    });

    // Earn Currency on positive interactions
    if (affinityDelta > 0) {
      const earnAmount = Math.ceil(affinityDelta * 10 * (prestigeLevel + 1));
      setCurrency(prev => prev + earnAmount);
    }
  };

  const loadCheckpoint = (name: string) => {
    const cp = checkpoints.find(c => c.name === name);
    if (cp) {
      setAffinity(cp.affinity);
      setMessages(cp.chatHistory);
      setCurrency(cp.currency);
      setPrestigeLevel(cp.prestige);
      // Restore items
      setStoreItems(prev => prev.map(i => cp.inventory.includes(i.id) ? { ...i, purchased: true } : i));

      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `Timeline [${name}] Restored.`, timestamp: Date.now() }]);
      addLog(`Restored Checkpoint: ${name}`);
    } else {
       addLog(`Failed to load Checkpoint: ${name}`);
    }
  };

  const handleCommand = (text: string): boolean => {
    // Checkpoint System
    const cpMatch = text.match(/^\/checkpoint\s+(.+)$/);
    if (cpMatch) {
      const name = cpMatch[1];
      const newCp: Checkpoint = {
        name,
        timestamp: Date.now(),
        affinity: { ...affinity },
        chatHistory: [...messages],
        currency,
        prestige: prestigeLevel,
        inventory: storeItems.filter(i => i.purchased).map(i => i.id)
      };
      setCheckpoints(prev => [...prev, newCp]);
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `Checkpoint [${name}] saved. Affinity & Economy States Secured.`, timestamp: Date.now() }]);
      return true;
    }

    // Load System
    const loadMatch = text.match(/^\/load\s+(.+)$/);
    if (loadMatch) {
      loadCheckpoint(loadMatch[1]);
      return true;
    }

    if (text === '/MasterHidden') {
      setMasterHiddenOpen(true);
      return true;
    }

    // Ability Commands
    const purchasedIds = storeItems.filter(i => i.purchased).map(i => i.id);

    if (text === '/Logic-Gates') {
       if (purchasedIds.includes('logic_gates')) {
         setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: '⚡ LOGIC GATES PROTOCOL: Provide Boolean Input.', timestamp: Date.now() }]);
       } else {
         setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: '🔒 LOCKED: Purchase "Logic Gates Protocol" in Store.', timestamp: Date.now() }]);
       }
       return true;
    }

    if (text === '/Challenges') {
       if (purchasedIds.includes('challenges')) {
         setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: '⚠️ CHALLENGE INITIATED: Prepare for affinity stress test.', timestamp: Date.now() }]);
       } else {
         setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: '🔒 LOCKED: Purchase "Simulated Crisis" in Store.', timestamp: Date.now() }]);
       }
       return true;
    }

    // Guidance Command
    if (text === '/guidance') {
      if (affinity.score >= UNLOCK_CUSTOM_THRESHOLD) {
         setIsCustomPanelOpen(true);
      } else {
         setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `🔒 LOCKED: Requires ${UNLOCK_CUSTOM_THRESHOLD}% Affinity. Current: ${affinity.score.toFixed(1)}%`, timestamp: Date.now() }]);
      }
      return true;
    }

    return false;
  };

  const handleSendMessage = async (overrideText?: string, specificMoE?: MoEType) => {
    const textToSend = overrideText || inputValue;
    if (!textToSend.trim()) return;

    if (handleCommand(textToSend)) {
      setInputValue('');
      return;
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: textToSend,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setIsProcessing(true);
    setStopSignal(false);
    setFoxTip(prev => ({ ...prev, visible: false }));

    const currentMoE = specificMoE || activeMoE;

    try {
      const purchasedIds = storeItems.filter(i => i.purchased).map(i => i.id);

      const { data, isCoT } = await generateResponse(
        messages, 
        textToSend, 
        settings, 
        currentMoE, 
        affinity.score,
        customInstructions,
        purchasedIds
      );

      if (stopSignal) {
        setIsProcessing(false);
        return;
      }

      // Update Affinity & Currency based on AI judgment
      updateAffinityAndCurrency(data.affinity_delta);

      if (currentMoE === MoEType.FOX || data.fox_tip) {
         if (data.fox_tip) setFoxTip({ text: data.fox_tip, visible: true });
         addLog("Fox tip active");
      }

      const modelMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: currentMoE === MoEType.ALIEN ? 'alien' : (currentMoE === MoEType.REVIEWER ? 'expert' : 'model'),
        content: data.response,
        timestamp: Date.now(),
        isCoT: isCoT,
        ritual: data.ritual,
        followups: data.follow_ups,
        expertType: currentMoE !== MoEType.NONE && currentMoE !== MoEType.DEVOTED ? currentMoE : undefined
      };

      setMessages(prev => [...prev, modelMsg]);

      if (settings.voiceMode) {
           const utterance = new SpeechSynthesisUtterance(data.response.substring(0, 200));
           window.speechSynthesis.speak(utterance);
      }

    } catch (e) {
      addLog(`Error: ${e}`);
    } finally {
      setIsProcessing(false);
    }
  };

  const stopGeneration = () => {
    setStopSignal(true);
    setIsProcessing(false);
    addLog("User triggered Graceful Stop");
  };

  // --- Render ---

  return (
    <div className="flex h-screen bg-[#050505] text-gray-100 font-sans overflow-hidden">

      {/* --- LEFT SIDEBAR (Navigation & Status) --- */}
      <div className={`${isLeftSidebarOpen ? 'w-64' : 'w-16'} bg-gray-950 border-r border-gray-800 transition-all duration-300 flex flex-col z-20`}>
         <div className="p-4 flex items-center justify-between border-b border-gray-800 h-16">
             {isLeftSidebarOpen && <span className="font-mono font-bold text-cyan-500 tracking-widest">NEXUS.AI</span>}
            <button onClick={() => setIsLeftSidebarOpen(!isLeftSidebarOpen)} className="text-gray-500 hover:text-white">
              {isLeftSidebarOpen ? '«' : '»'}
            </button>
         </div>

         <div className="flex-1 overflow-y-auto p-2 space-y-2">
            <button onClick={() => setActivePanel('folder')} className={`w-full p-2 rounded hover:bg-gray-800 flex items-center ${isLeftSidebarOpen ? 'justify-start gap-3' : 'justify-center'}`} title="Saved Data">
              <span>📂</span> {isLeftSidebarOpen && <span className="text-sm font-mono text-gray-300">DATA_BANKS</span>}
            </button>
            <button onClick={handleNewChat} className={`w-full p-2 rounded hover:bg-gray-800 flex items-center ${isLeftSidebarOpen ? 'justify-start gap-3' : 'justify-center'}`} title="New Chat">
              <span>💬</span> {isLeftSidebarOpen && <span className="text-sm font-mono text-gray-300">NEW_SESSION</span>}
            </button>
            <button onClick={() => setActivePanel('store')} className={`w-full p-2 rounded hover:bg-gray-800 flex items-center ${isLeftSidebarOpen ? 'justify-start gap-3' : 'justify-center'}`} title="Marketplace">
              <span>🛒</span> {isLeftSidebarOpen && <span className="text-sm font-mono text-gray-300">MARKETPLACE</span>}
            </button>
            <button onClick={() => setActivePanel('settings')} className={`w-full p-2 rounded hover:bg-gray-800 flex items-center ${isLeftSidebarOpen ? 'justify-start gap-3' : 'justify-center'}`} title="Settings">
              <span>⚙️</span> {isLeftSidebarOpen && <span className="text-sm font-mono text-gray-300">SYS_CONFIG</span>}
            </button>

            <div className="border-t border-gray-800 my-2 pt-2">
               {/* Currency Display */}
               <div className={`p-2 rounded bg-gray-900 border border-gray-800 mb-2 ${!isLeftSidebarOpen && 'text-center'}`}>
                  <span className="text-emerald-400 font-mono font-bold">💲 {currency}</span>
               </div>

               {/* Affinity */}
               <div className={`text-xs text-gray-500 mb-2 font-mono ${!isLeftSidebarOpen && 'text-center'}`}>
                 {isLeftSidebarOpen ? 'AFFINITY LEVEL' : 'LVL'}
               </div>
               {isLeftSidebarOpen ? (
                 <div className="px-2">
                   <div className="flex justify-between text-xs text-cyan-400 mb-1">
                     <span>Trust</span>
                     <span>{affinity.score.toFixed(0)}%</span>
                   </div>
                   <div className="h-1 bg-gray-800 rounded-full overflow-hidden">
                     <div className="h-full bg-cyan-500 transition-all duration-500" style={{ width: `${affinity.score}%` }} />
                   </div>
                   {affinity.score >= MAX_TIER_PRESTIGE_THRESHOLD && (
                      <button onClick={handlePrestige} className="mt-2 w-full text-xs bg-purple-900/50 text-purple-300 border border-purple-500 rounded py-1 hover:bg-purple-800 animate-pulse">
                         🐇 PRESTIGE AVAIL
                      </button>
                   )}
                 </div>
               ) : (
                  <div className="flex justify-center text-xs text-cyan-400 font-bold">{affinity.score.toFixed(0)}%</div>
               )}
            </div>
         </div>
      </div>

      {/* --- CENTER (Main Chat) --- */}
      <div className="flex-1 flex flex-col min-w-0 relative bg-[#050505]">
        <VisualSynth isActive={isProcessing} voiceMode={settings.voiceMode} affinity={affinity.score} />
        <AffinityBar affinity={affinity} />

        {/* Custom Instructions Toggle (Top Right Overlay) */}
        {affinity.score >= UNLOCK_CUSTOM_THRESHOLD && (
          <div className="absolute top-36 right-4 z-30">
            <button 
              onClick={() => setIsCustomPanelOpen(!isCustomPanelOpen)}
              className={`flex items-center gap-2 px-3 py-1 rounded-full text-xs font-mono border ${isCustomPanelOpen ? 'bg-cyan-900 border-cyan-400 text-white' : 'bg-black/50 border-gray-700 text-gray-400'}`}
            >
              <span>+</span> CUSTOM_GUIDANCE
            </button>
          </div>
        )}

        {/* Custom Panel Overlay */}
        {isCustomPanelOpen && (
          <div className="absolute top-44 right-4 z-30 w-80 bg-black/90 border border-cyan-500/50 p-4 rounded-lg shadow-xl backdrop-blur-md animate-in slide-in-from-right-10">
             <div className="flex justify-between items-center mb-2">
               <h3 className="text-cyan-400 font-mono text-sm">USER_OVERRIDE_PROTOCOL</h3>
               <button onClick={() => setIsCustomPanelOpen(false)} className="text-gray-500 hover:text-white">✕</button>
             </div>
             <textarea 
               className="w-full h-40 bg-gray-900 border border-gray-700 text-xs text-gray-300 p-2 font-mono focus:border-cyan-500 outline-none rounded"
               placeholder="Enter custom directives (>65% Affinity Required). Max 2000 chars."
               maxLength={2000}
               value={customInstructions}
               onChange={(e) => setCustomInstructions(e.target.value)}
             />
             <div className="text-right text-[10px] text-gray-500 mt-1">{customInstructions.length}/2000</div>
          </div>
        )}

        <div className="flex-1 overflow-y-auto p-4 space-y-6 scroll-smooth">
          {messages.map((msg) => (
            <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} animate-fadeIn`}>

              {/* Message Bubble */}
              <div 
                className={`
                  max-w-[85%] p-4 rounded-lg nanite-border relative flex flex-col gap-2
                  ${msg.role === 'user' ? 'bg-cyan-950/30 text-cyan-50 border-cyan-800' : ''}
                  ${msg.role === 'model' ? 'bg-gray-900/50 text-gray-200 border-gray-800' : ''}
                  ${msg.role === 'system' ? 'bg-red-900/10 text-red-200 border-red-900/30 w-full text-center font-mono text-xs' : ''}
                  ${msg.role === 'expert' ? 'bg-purple-900/20 text-purple-200 border-purple-500/30' : ''}
                  ${msg.role === 'alien' ? 'bg-emerald-900/20 text-emerald-200 border-emerald-500/30' : ''}
                `}
              >
                {/* Ritual Header */}
                {msg.ritual && (
                  <div className="text-[10px] uppercase font-mono tracking-widest text-cyan-500/80 border-b border-cyan-900/50 pb-1 mb-1">
                    {msg.ritual}
                  </div>
                )}

                {/* Main Content */}
                <div className="whitespace-pre-wrap leading-relaxed">
                  {msg.content}
                </div>

                {/* Follow-up Questions */}
                {msg.followups && msg.followups.length > 0 && (
                   <div className="mt-4 pt-2 border-t border-gray-800/50 flex flex-wrap gap-2">
                      {msg.followups.map((q, i) => (
                        <button 
                          key={i} 
                          onClick={() => handleSendMessage(q)}
                          className="text-[10px] bg-gray-900 hover:bg-cyan-900/40 border border-gray-700 hover:border-cyan-500 text-gray-400 hover:text-cyan-300 px-2 py-1 rounded transition-colors text-left"
                        >
                          {q} ↗
                        </button>
                      ))}
                   </div>
                )}

                {msg.role !== 'system' && (
                  <div className="text-[10px] text-gray-600 font-mono text-right mt-1">
                    T+{Math.floor((Date.now() - msg.timestamp)/1000)}s
                  </div>
                )}
              </div>
            </div>
          ))}
          <div ref={messagesEndRef} />
        </div>

        {/* Fox Popup */}
        {foxTip.visible && (
          <div className="absolute bottom-24 right-8 max-w-xs animate-in slide-in-from-bottom-5 fade-in duration-300 bg-orange-950/95 text-orange-200 p-4 rounded-xl border border-orange-500/50 shadow-2xl z-30 backdrop-blur-md">
             <div className="absolute -top-4 -left-4 text-3xl bg-black rounded-full p-1 border border-orange-900">🦊</div>
             <p className="text-sm font-bold italic pl-2">"{foxTip.text}"</p>
             <button onClick={() => setFoxTip({text:'', visible:false})} className="absolute top-1 right-2 text-xs text-orange-500 hover:text-white">✕</button>
          </div>
        )}

        {/* Input Deck */}
        <div className="p-4 bg-gray-950 border-t border-gray-800 z-20">
          <div className="flex gap-2 mb-3 justify-center">
            <button title="Review Expert" onClick={() => handleSendMessage(messages[messages.length-1]?.content || "Review", MoEType.REVIEWER)} className="p-2 bg-gray-900 hover:bg-purple-900/30 rounded border border-gray-700 hover:border-purple-500 transition active:scale-95">🕵️</button>
            <button title="Alien Follow-Through" onClick={() => handleSendMessage(messages[messages.length-1]?.content || "Question", MoEType.ALIEN)} className="p-2 bg-gray-900 hover:bg-emerald-900/30 rounded border border-gray-700 hover:border-emerald-500 transition active:scale-95">👽</button>
            <button title="Quick Fox Tip" onClick={() => handleSendMessage(messages[messages.length-1]?.content || "Tip", MoEType.FOX)} className="p-2 bg-gray-900 hover:bg-orange-900/30 rounded border border-gray-700 hover:border-orange-500 transition active:scale-95">🦊</button>
            <button title="URGENT SOLVE" onClick={() => handleSendMessage(messages[messages.length-1]?.content || "SOLVE", MoEType.URGENT)} className="p-2 bg-gray-900 hover:bg-red-900/30 rounded border border-gray-700 hover:border-red-500 transition active:scale-95">🔥</button>
            <button title="Devoted Toggle" onClick={() => { const newMode = activeMoE === MoEType.DEVOTED ? MoEType.NONE : MoEType.DEVOTED; setActiveMoE(newMode); addLog(`Devotion Mode: ${newMode}`); }} className={`p-2 rounded border transition active:scale-95 ${activeMoE === MoEType.DEVOTED ? 'bg-pink-900/30 border-pink-500 shadow-[0_0_10px_rgba(236,72,153,0.3)]' : 'bg-gray-900 border-gray-700'}`}>❤️‍🔥</button>
          </div>

          <div className="flex gap-2 relative">
            <input
              type="text"
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && handleSendMessage()}
              placeholder={activeMoE === MoEType.DEVOTED ? "Speak, I am listening..." : "Ask anything... (/guidance for custom)"}
              className="flex-1 bg-black/50 border border-gray-800 text-gray-200 px-4 py-3 rounded-md focus:outline-none focus:border-cyan-500 focus:shadow-[0_0_15px_rgba(6,182,212,0.1)] font-mono text-sm"
              disabled={isProcessing}
            />
            {isProcessing ? (
              <button onClick={stopGeneration} className="px-6 bg-red-900/20 border border-red-500 text-red-500 rounded hover:bg-red-900/40 transition">⏹️</button>
            ) : (
              <button onClick={() => handleSendMessage()} className="px-6 bg-cyan-900/20 border border-cyan-600 text-cyan-400 rounded hover:bg-cyan-900/40 transition">SEND</button>
            )}
          </div>
          <div className="text-[10px] text-gray-600 mt-2 font-mono flex justify-between">
            <span>AFFINITY: {affinity.score.toFixed(1)}%</span>
            <span>STATUS: {isProcessing ? 'COMPUTING...' : 'IDLE'}</span>
          </div>
        </div>
      </div>

      {/* --- RIGHT SIDEBAR (CoT Visualizer) --- */}
      <div className={`${isRightSidebarOpen ? 'w-72' : 'w-0'} bg-gray-950 border-l border-gray-800 transition-all duration-300 flex flex-col z-20 overflow-hidden`}>
         <div className="p-4 flex items-center justify-between border-b border-gray-800 h-16 shrink-0">
             <div className="flex items-center gap-2 overflow-hidden">
                <span className="text-xl">🧠</span>
                <span className="font-mono font-bold text-purple-400 text-xs tracking-wider whitespace-nowrap">NEURAL_STREAM</span>
             </div>
             <button onClick={() => setIsRightSidebarOpen(!isRightSidebarOpen)} className="text-gray-500 hover:text-white">✕</button>
         </div>
         <div className="flex-1 overflow-y-auto p-4 space-y-4 font-mono">
            {isProcessing && <div className="text-xs text-purple-500 animate-pulse">PROCESSING INPUT VECTOR...</div>}
            {/* Display active CoT steps */}
            {messages.slice().reverse().find(m => m.isCoT && m.cotSteps)?.cotSteps?.map((step, i) => (
               <div key={i} className="p-2 border-l-2 border-purple-800 bg-purple-900/10 text-xs text-purple-200">
                 <span className="text-purple-500 font-bold mr-1">STEP {i+1}:</span> {step.replace('Step ' + (i+1) + ':', '')}
               </div>
            ))}
         </div>
         <div className="p-4 border-t border-gray-800 shrink-0">
            <label className="flex items-center justify-between text-xs text-gray-400 cursor-pointer hover:text-white">
              <span>Show Thinking</span>
              <input type="checkbox" checked={settings.showThinking} onChange={(e) => setSettings({...settings, showThinking: e.target.checked})} className="accent-purple-500" />
            </label>
         </div>
      </div>

      {!isRightSidebarOpen && <button onClick={() => setIsRightSidebarOpen(true)} className="absolute top-4 right-4 z-10 p-2 bg-gray-900 border border-gray-700 rounded hover:border-purple-500 text-purple-400">🧠</button>}

      {/* --- OVERLAYS --- */}

      {/* Store Overlay */}
      {activePanel === 'store' && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-sm flex items-center justify-center">
           <div className="w-full max-w-2xl bg-gray-950 border border-emerald-900 rounded-lg p-6 shadow-2xl relative">
              <button onClick={() => setActivePanel(null)} className="absolute top-4 right-4 text-gray-500 hover:text-white">✕</button>
              <h2 className="text-xl font-mono text-emerald-500 mb-6 flex items-center gap-2">🛒 MARKETPLACE <span className="text-sm text-gray-500">| BAL: 💲{currency}</span></h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 {storeItems.map((item) => (
                    <div key={item.id} className={`p-4 border rounded ${item.purchased ? 'border-emerald-500/30 bg-emerald-900/10' : 'border-gray-800 bg-gray-900'}`}>
                       <div className="flex justify-between items-start mb-2">
                          <span className="text-2xl">{item.icon}</span>
                          {item.purchased ? <span className="text-xs text-emerald-500 font-bold">OWNED</span> : <span className="text-xs text-yellow-500 font-bold">💲{item.cost}</span>}
                       </div>
                       <h3 className="font-bold text-gray-200">{item.name}</h3>
                       <p className="text-xs text-gray-500 mt-1 mb-3">{item.description}</p>
                       {!item.purchased && (
                          <button 
                             onClick={() => handlePurchase(item)} 
                             disabled={currency < item.cost}
                             className={`w-full py-1 text-xs rounded ${currency >= item.cost ? 'bg-emerald-700 text-white hover:bg-emerald-600' : 'bg-gray-800 text-gray-600 cursor-not-allowed'}`}
                          >
                             PURCHASE
                          </button>
                       )}
                    </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      {/* Folder Overlay */}
      {activePanel === 'folder' && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-sm flex items-center justify-center">
           <div className="w-full max-w-lg bg-gray-950 border border-cyan-900 rounded-lg p-6 shadow-2xl relative">
              <button onClick={() => setActivePanel(null)} className="absolute top-4 right-4 text-gray-500 hover:text-white">✕</button>
              <h2 className="text-xl font-mono text-cyan-500 mb-6">📂 DATA_BANKS</h2>
              <div className="space-y-2 max-h-96 overflow-y-auto">
                 {checkpoints.length === 0 ? <p className="text-gray-600 text-sm">No saved data found.</p> : checkpoints.map((cp, i) => (
                    <div key={i} className="flex justify-between items-center p-3 border border-gray-800 rounded hover:bg-gray-900">
                       <div>
                          <div className="text-sm font-bold text-gray-300">{cp.name}</div>
                          <div className="text-xs text-gray-500">{new Date(cp.timestamp).toLocaleDateString()} | Affinity: {cp.affinity.score.toFixed(0)}%</div>
                       </div>
                       <button onClick={() => { loadCheckpoint(cp.name); setActivePanel(null); }} className="text-xs bg-cyan-900/30 text-cyan-400 px-3 py-1 hover:bg-cyan-900/60 rounded">LOAD</button>
                    </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      {/* Settings Overlay */}
      <SettingsPanel 
        isOpen={activePanel === 'settings'} 
        type="settings"
        onClose={() => setActivePanel(null)}
        settings={settings}
        onSettingsChange={setSettings}
        history={messages}
        checkpoints={checkpoints}
        onLoadCheckpoint={loadCheckpoint}
        logs={logs}
      />

      {/* History Overlay */}
      <SettingsPanel 
        isOpen={activePanel === 'history'} 
        type="history"
        onClose={() => setActivePanel(null)}
        settings={settings}
        onSettingsChange={setSettings}
        history={messages}
        checkpoints={checkpoints}
        onLoadCheckpoint={loadCheckpoint}
        logs={logs}
      />

    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import VisualSynth from './components/VisualSynth';
import AffinityBar from './components/AffinityBar';
import SettingsPanel from './components/SettingsPanel';
import { generateResponse } from './services/geminiService';
import { Message, AffinityState, Settings, Checkpoint, MoEType, FoxTip, StoreItem } from './types';
import { 
  INITIAL_AFFINITY_SCORE, 
  LOGIC_GATES_ABILITY, 
  CHALLENGES_ABILITY, 
  INITIAL_STORE_ITEMS,
  UNLOCK_CUSTOM_THRESHOLD,
  MAX_TIER_PRESTIGE_THRESHOLD
} from './constants';

const App: React.FC = () => {
  // --- State ---
  const [messages, setMessages] = useState<Message[]>([
    { id: '0', role: 'system', content: 'Earned Affinity Interface Initialized. Nanite Systems Online.', timestamp: Date.now() }
  ]);
  const [inputValue, setInputValue] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [stopSignal, setStopSignal] = useState(false);

  // Progression & Economy
  const [affinity, setAffinity] = useState<AffinityState>({
    score: INITIAL_AFFINITY_SCORE,
    level: 1,
    abilities: [],
    negativeStats: 0
  });
  const [currency, setCurrency] = useState(0);
  const [prestigeLevel, setPrestigeLevel] = useState(0);
  const [storeItems, setStoreItems] = useState<StoreItem[]>(INITIAL_STORE_ITEMS);

  // Settings & Customization
  const [settings, setSettings] = useState<Settings>({
    showThinking: false,
    voiceMode: false,
    devMode: false,
    instructionLength: 'regular'
  });
  const [customInstructions, setCustomInstructions] = useState('');
  const [isCustomPanelOpen, setIsCustomPanelOpen] = useState(false);

  // UI State
  const [isLeftSidebarOpen, setIsLeftSidebarOpen] = useState(true);
  const [isRightSidebarOpen, setIsRightSidebarOpen] = useState(true);
  const [isVisualSynthOpen, setIsVisualSynthOpen] = useState(true);
  const [activePanel, setActivePanel] = useState<'history' | 'settings' | 'store' | 'folder' | null>(null);

  const [checkpoints, setCheckpoints] = useState<Checkpoint[]>([]);
  const [logs, setLogs] = useState<string[]>([]);
  const [foxTip, setFoxTip] = useState<FoxTip>({ text: '', visible: false });
  const [activeMoE, setActiveMoE] = useState<MoEType>(MoEType.NONE);
  const [masterHiddenOpen, setMasterHiddenOpen] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  // --- Effects ---

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, foxTip.visible]);

  // Load Persistence
  useEffect(() => {
    const savedAffinity = localStorage.getItem('ea_affinity');
    const savedCheckpoints = localStorage.getItem('ea_checkpoints');
    const savedCurrency = localStorage.getItem('ea_currency');
    const savedPrestige = localStorage.getItem('ea_prestige');
    const savedItems = localStorage.getItem('ea_store');

    if (savedAffinity) setAffinity(JSON.parse(savedAffinity));
    if (savedCheckpoints) setCheckpoints(JSON.parse(savedCheckpoints));
    if (savedCurrency) setCurrency(parseInt(savedCurrency));
    if (savedPrestige) setPrestigeLevel(parseInt(savedPrestige));
    if (savedItems) setStoreItems(JSON.parse(savedItems));
  }, []);

  // Save Persistence
  useEffect(() => { localStorage.setItem('ea_affinity', JSON.stringify(affinity)); }, [affinity]);
  useEffect(() => { localStorage.setItem('ea_checkpoints', JSON.stringify(checkpoints)); }, [checkpoints]);
  useEffect(() => { localStorage.setItem('ea_currency', JSON.stringify(currency)); }, [currency]);
  useEffect(() => { localStorage.setItem('ea_prestige', JSON.stringify(prestigeLevel)); }, [prestigeLevel]);
  useEffect(() => { localStorage.setItem('ea_store', JSON.stringify(storeItems)); }, [storeItems]);

  // --- Logic Helpers ---

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev]);
  };

  const handleNewChat = () => {
    // Auto-save checkpoint before clearing
    const autoSaveName = `AutoSave_${new Date().toLocaleDateString()}_${new Date().toLocaleTimeString()}`;
    const newCp: Checkpoint = {
      name: autoSaveName,
      timestamp: Date.now(),
      affinity: { ...affinity },
      chatHistory: [...messages],
      currency,
      prestige: prestigeLevel,
      inventory: storeItems.filter(i => i.purchased).map(i => i.id)
    };
    setCheckpoints(prev => [...prev, newCp]);

    setMessages([{ id: Date.now().toString(), role: 'system', content: 'Buffer cleared. New session initialized.', timestamp: Date.now() }]);
    addLog('New Chat Initialized (Old chat autosaved)');
  };

  const handlePrestige = () => {
    if (affinity.score < MAX_TIER_PRESTIGE_THRESHOLD) return;

    const confirmPrestige = window.confirm("🐇 PRESTIGE PROTOCOL: Reset Affinity to 0%? You will keep Currency, Items, and Chat History, but gain a Tier Level.");
    if (!confirmPrestige) return;

    setPrestigeLevel(prev => prev + 1);
    setAffinity(prev => ({ ...prev, score: 0, level: prev.level + 1 }));
    setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `🐇 PRESTIGE ASCENSION: TIER ${prestigeLevel + 1} ACTIVE.`, timestamp: Date.now() }]);
    addLog(`Prestige Tier ${prestigeLevel + 1} Achieved`);
  };

  const handlePurchase = (item: StoreItem) => {
    if (currency >= item.cost && !item.purchased) {
      setCurrency(prev => prev - item.cost);
      setStoreItems(prev => prev.map(i => i.id === item.id ? { ...i, purchased: true } : i));
      addLog(`Purchased ${item.name}`);

      // Immediate Unlock Logic
      if (item.id === 'logic_gates') {
        setAffinity(prev => ({...prev, abilities: [...prev.abilities, LOGIC_GATES_ABILITY]}));
      } else if (item.id === 'challenges') {
        setAffinity(prev => ({...prev, abilities: [...prev.abilities, CHALLENGES_ABILITY]}));
      }
    }
  };

  const updateAffinityAndCurrency = (affinityDelta: number) => {
    setAffinity(prev => {
      let newScore = Math.min(100, Math.max(0, prev.score + affinityDelta));
      return {
        ...prev,
        score: newScore,
        negativeStats: affinityDelta < 0 ? prev.negativeStats + Math.abs(affinityDelta) : prev.negativeStats
      };
    });

    // Earn Currency on positive interactions
    if (affinityDelta > 0) {
      const earnAmount = Math.ceil(affinityDelta * 10 * (prestigeLevel + 1));
      setCurrency(prev => prev + earnAmount);
    }
  };

  const loadCheckpoint = (name: string) => {
    const cp = checkpoints.find(c => c.name === name);
    if (cp) {
      setAffinity(cp.affinity);
      setMessages(cp.chatHistory);
      setCurrency(cp.currency);
      setPrestigeLevel(cp.prestige);
      // Restore items
      setStoreItems(prev => prev.map(i => cp.inventory.includes(i.id) ? { ...i, purchased: true } : i));

      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `Timeline [${name}] Restored.`, timestamp: Date.now() }]);
      addLog(`Restored Checkpoint: ${name}`);
    } else {
       addLog(`Failed to load Checkpoint: ${name}`);
    }
  };

  const handleCommand = (text: string): boolean => {
    // Master Hidden Set Affinity
    const masterSetMatch = text.match(/^\/MasterHidden\s+set-affinity\s+(\d+(\.\d+)?)$/);
    if (masterSetMatch) {
       const newScore = parseFloat(masterSetMatch[1]);
       const validScore = Math.min(100, Math.max(0, newScore));
       setAffinity(prev => ({ ...prev, score: validScore }));
       setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `>> OVERRIDE: Affinity forced to ${validScore.toFixed(1)}%.`, timestamp: Date.now() }]);
       addLog(`Master Override: Affinity set to ${validScore}`);
       return true;
    }

    // Checkpoint System
    const cpMatch = text.match(/^\/checkpoint\s+(.+)$/);
    if (cpMatch) {
      const name = cpMatch[1];
      const newCp: Checkpoint = {
        name,
        timestamp: Date.now(),
        affinity: { ...affinity },
        chatHistory: [...messages],
        currency,
        prestige: prestigeLevel,
        inventory: storeItems.filter(i => i.purchased).map(i => i.id)
      };
      setCheckpoints(prev => [...prev, newCp]);
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `Checkpoint [${name}] saved. Affinity & Economy States Secured.`, timestamp: Date.now() }]);
      return true;
    }

    // Load System
    const loadMatch = text.match(/^\/load\s+(.+)$/);
    if (loadMatch) {
      loadCheckpoint(loadMatch[1]);
      return true;
    }

    // Master Hidden Toggle
    if (text === '/MasterHidden') {
      setMasterHiddenOpen(true);
      return true;
    }

    // Ability Commands
    const purchasedIds = storeItems.filter(i => i.purchased).map(i => i.id);

    if (text === '/Logic-Gates') {
       if (purchasedIds.includes('logic_gates')) {
         setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: '⚡ LOGIC GATES PROTOCOL: Provide Boolean Input.', timestamp: Date.now() }]);
       } else {
         setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: '🔒 LOCKED: Purchase "Logic Gates Protocol" in Store.', timestamp: Date.now() }]);
       }
       return true;
    }

    if (text === '/Challenges') {
       if (purchasedIds.includes('challenges')) {
         setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: '⚠️ CHALLENGE INITIATED: Prepare for affinity stress test.', timestamp: Date.now() }]);
       } else {
         setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: '🔒 LOCKED: Purchase "Simulated Crisis" in Store.', timestamp: Date.now() }]);
       }
       return true;
    }

    // Guidance Command
    if (text === '/guidance') {
      if (affinity.score >= UNLOCK_CUSTOM_THRESHOLD) {
         setIsCustomPanelOpen(true);
      } else {
         setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `🔒 LOCKED: Requires ${UNLOCK_CUSTOM_THRESHOLD}% Affinity. Current: ${affinity.score.toFixed(1)}%`, timestamp: Date.now() }]);
      }
      return true;
    }

    return false;
  };

  const handleSendMessage = async (overrideText?: string, specificMoE?: MoEType) => {
    const textToSend = overrideText || inputValue;
    if (!textToSend.trim()) return;

    if (handleCommand(textToSend)) {
      setInputValue('');
      return;
    }

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: textToSend,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setIsProcessing(true);
    setStopSignal(false);
    setFoxTip(prev => ({ ...prev, visible: false }));

    const currentMoE = specificMoE || activeMoE;

    // Stop any existing speech when new turn starts
    window.speechSynthesis.cancel();

    try {
      const purchasedIds = storeItems.filter(i => i.purchased).map(i => i.id);

      const { data, isCoT } = await generateResponse(
        messages, 
        textToSend, 
        settings, 
        currentMoE, 
        affinity.score,
        customInstructions,
        purchasedIds
      );

      if (stopSignal) {
        setIsProcessing(false);
        return;
      }

      // Update Affinity & Currency based on AI judgment
      updateAffinityAndCurrency(data.affinity_delta);

      if (currentMoE === MoEType.FOX || data.fox_tip) {
         if (data.fox_tip) setFoxTip({ text: data.fox_tip, visible: true });
         addLog("Fox tip active");
      }

      const modelMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: currentMoE === MoEType.ALIEN ? 'alien' : (currentMoE === MoEType.REVIEWER ? 'expert' : 'model'),
        content: data.response,
        timestamp: Date.now(),
        isCoT: isCoT,
        ritual: data.ritual,
        followups: data.follow_ups,
        expertType: currentMoE !== MoEType.NONE && currentMoE !== MoEType.DEVOTED ? currentMoE : undefined
      };

      setMessages(prev => [...prev, modelMsg]);

      // Voice Output Logic
      if (settings.voiceMode) {
           const utterance = new SpeechSynthesisUtterance(data.response);
           // Optional: Clean up text (remove markdown like ** or *) for better speech
           utterance.text = data.response.replace(/[*#]/g, '');
           utterance.rate = 1.0;
           utterance.pitch = 1.0;
           window.speechSynthesis.speak(utterance);
      }

    } catch (e) {
      addLog(`Error: ${e}`);
    } finally {
      setIsProcessing(false);
    }
  };

  const stopGeneration = () => {
    setStopSignal(true);
    setIsProcessing(false);
    window.speechSynthesis.cancel();
    addLog("User triggered Graceful Stop");
  };

  // --- Render ---

  return (
    <div className="flex h-screen bg-[#050505] text-gray-100 font-sans overflow-hidden">

      {/* --- LEFT SIDEBAR (Navigation & Status) --- */}
      <div className={`${isLeftSidebarOpen ? 'w-64' : 'w-16'} bg-gray-950 border-r border-gray-800 transition-all duration-300 flex flex-col z-20`}>
         <div className="p-4 flex items-center justify-between border-b border-gray-800 h-16">
             {isLeftSidebarOpen && <span className="font-mono font-bold text-cyan-500 tracking-widest">NEXUS.AI</span>}
            <button onClick={() => setIsLeftSidebarOpen(!isLeftSidebarOpen)} className="text-gray-500 hover:text-white">
              {isLeftSidebarOpen ? '«' : '»'}
            </button>
         </div>

         <div className="flex-1 overflow-y-auto p-2 space-y-2">
            <button onClick={() => setActivePanel('folder')} className={`w-full p-2 rounded hover:bg-gray-800 flex items-center ${isLeftSidebarOpen ? 'justify-start gap-3' : 'justify-center'}`} title="Saved Data">
              <span>📂</span> {isLeftSidebarOpen && <span className="text-sm font-mono text-gray-300">DATA_BANKS</span>}
            </button>
            <button onClick={handleNewChat} className={`w-full p-2 rounded hover:bg-gray-800 flex items-center ${isLeftSidebarOpen ? 'justify-start gap-3' : 'justify-center'}`} title="New Chat">
              <span>💬</span> {isLeftSidebarOpen && <span className="text-sm font-mono text-gray-300">NEW_SESSION</span>}
            </button>
            <button onClick={() => setActivePanel('store')} className={`w-full p-2 rounded hover:bg-gray-800 flex items-center ${isLeftSidebarOpen ? 'justify-start gap-3' : 'justify-center'}`} title="Marketplace">
              <span>🛒</span> {isLeftSidebarOpen && <span className="text-sm font-mono text-gray-300">MARKETPLACE</span>}
            </button>
            <button onClick={() => setActivePanel('settings')} className={`w-full p-2 rounded hover:bg-gray-800 flex items-center ${isLeftSidebarOpen ? 'justify-start gap-3' : 'justify-center'}`} title="Settings">
              <span>⚙️</span> {isLeftSidebarOpen && <span className="text-sm font-mono text-gray-300">SYS_CONFIG</span>}
            </button>

            <div className="border-t border-gray-800 my-2 pt-2">
               {/* Currency Display */}
               <div className={`p-2 rounded bg-gray-900 border border-gray-800 mb-2 ${!isLeftSidebarOpen && 'text-center'}`}>
                  <span className="text-emerald-400 font-mono font-bold">💲 {currency}</span>
               </div>

               {/* Affinity */}
               <div className={`text-xs text-gray-500 mb-2 font-mono ${!isLeftSidebarOpen && 'text-center'}`}>
                 {isLeftSidebarOpen ? 'AFFINITY LEVEL' : 'LVL'}
               </div>
               {isLeftSidebarOpen ? (
                 <div className="px-2">
                   <div className="flex justify-between text-xs text-cyan-400 mb-1">
                     <span>Trust</span>
                     <span>{affinity.score.toFixed(0)}%</span>
                   </div>
                   <div className="h-1 bg-gray-800 rounded-full overflow-hidden">
                     <div className="h-full bg-cyan-500 transition-all duration-500" style={{ width: `${affinity.score}%` }} />
                   </div>
                   {affinity.score >= MAX_TIER_PRESTIGE_THRESHOLD && (
                      <button onClick={handlePrestige} className="mt-2 w-full text-xs bg-purple-900/50 text-purple-300 border border-purple-500 rounded py-1 hover:bg-purple-800 animate-pulse">
                         🐇 PRESTIGE AVAIL
                      </button>
                   )}
                 </div>
               ) : (
                  <div className="flex justify-center text-xs text-cyan-400 font-bold">{affinity.score.toFixed(0)}%</div>
               )}
            </div>
         </div>
      </div>

      {/* --- CENTER (Main Chat) --- */}
      <div className="flex-1 flex flex-col min-w-0 relative bg-[#050505]">

        {/* Center Top Control Bar */}
        <div className="flex justify-between items-center p-2 bg-gray-950 border-b border-gray-800 text-[10px] font-mono text-gray-500">
            <button 
              onClick={() => setIsVisualSynthOpen(!isVisualSynthOpen)} 
              className="hover:text-cyan-400 flex items-center gap-1 transition-colors"
            >
               {isVisualSynthOpen ? '👁️ HIDE_VISUALS' : '👁️ SHOW_VISUALS'}
            </button>
            <div className="flex items-center gap-3">
               {settings.voiceMode && (
                 <span className="text-emerald-500 flex items-center gap-1 animate-pulse">
                   <span>🔊</span> VOICE_ACTIVE
                 </span>
               )}
               <span>CPU: {isProcessing ? 'BUSY' : 'IDLE'}</span>
            </div>
        </div>

        {isVisualSynthOpen && <VisualSynth isActive={isProcessing} voiceMode={settings.voiceMode} affinity={affinity.score} />}
        <AffinityBar affinity={affinity} />

        {/* Custom Instructions Toggle (Top Right Overlay) */}
        {affinity.score >= UNLOCK_CUSTOM_THRESHOLD && (
          <div className="absolute top-48 right-4 z-30">
            <button 
              onClick={() => setIsCustomPanelOpen(!isCustomPanelOpen)}
              className={`flex items-center gap-2 px-3 py-1 rounded-full text-xs font-mono border ${isCustomPanelOpen ? 'bg-cyan-900 border-cyan-400 text-white' : 'bg-black/50 border-gray-700 text-gray-400'}`}
            >
              <span>+</span> CUSTOM_GUIDANCE
            </button>
          </div>
        )}

        {/* Custom Panel Overlay */}
        {isCustomPanelOpen && (
          <div className="absolute top-56 right-4 z-30 w-80 bg-black/90 border border-cyan-500/50 p-4 rounded-lg shadow-xl backdrop-blur-md animate-in slide-in-from-right-10">
             <div className="flex justify-between items-center mb-2">
               <h3 className="text-cyan-400 font-mono text-sm">USER_OVERRIDE_PROTOCOL</h3>
               <button onClick={() => setIsCustomPanelOpen(false)} className="text-gray-500 hover:text-white">✕</button>
             </div>
             <textarea 
               className="w-full h-40 bg-gray-900 border border-gray-700 text-xs text-gray-300 p-2 font-mono focus:border-cyan-500 outline-none rounded"
               placeholder="Enter custom directives (>65% Affinity Required). Max 2000 chars."
               maxLength={2000}
               value={customInstructions}
               onChange={(e) => setCustomInstructions(e.target.value)}
             />
             <div className="text-right text-[10px] text-gray-500 mt-1">{customInstructions.length}/2000</div>
          </div>
        )}

        <div className="flex-1 overflow-y-auto p-4 space-y-6 scroll-smooth">
          {messages.map((msg) => (
            <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} animate-fadeIn`}>

              {/* Message Bubble */}
              <div 
                className={`
                  max-w-[85%] p-4 rounded-lg nanite-border relative flex flex-col gap-2
                  ${msg.role === 'user' ? 'bg-cyan-950/30 text-cyan-50 border-cyan-800' : ''}
                  ${msg.role === 'model' ? 'bg-gray-900/50 text-gray-200 border-gray-800' : ''}
                  ${msg.role === 'system' ? 'bg-red-900/10 text-red-200 border-red-900/30 w-full text-center font-mono text-xs' : ''}
                  ${msg.role === 'expert' ? 'bg-purple-900/20 text-purple-200 border-purple-500/30' : ''}
                  ${msg.role === 'alien' ? 'bg-emerald-900/20 text-emerald-200 border-emerald-500/30' : ''}
                `}
              >
                {/* Ritual Header */}
                {msg.ritual && (
                  <div className="text-[10px] uppercase font-mono tracking-widest text-cyan-500/80 border-b border-cyan-900/50 pb-1 mb-1">
                    {msg.ritual}
                  </div>
                )}

                {/* Main Content */}
                <div className="whitespace-pre-wrap leading-relaxed">
                  {msg.content}
                </div>

                {/* Follow-up Questions */}
                {msg.followups && msg.followups.length > 0 && (
                   <div className="mt-4 pt-2 border-t border-gray-800/50 flex flex-wrap gap-2">
                      {msg.followups.map((q, i) => (
                        <button 
                          key={i} 
                          onClick={() => handleSendMessage(q)}
                          className="text-[10px] bg-gray-900 hover:bg-cyan-900/40 border border-gray-700 hover:border-cyan-500 text-gray-400 hover:text-cyan-300 px-2 py-1 rounded transition-colors text-left"
                        >
                          {q} ↗
                        </button>
                      ))}
                   </div>
                )}

                {msg.role !== 'system' && (
                  <div className="text-[10px] text-gray-600 font-mono text-right mt-1">
                    T+{Math.floor((Date.now() - msg.timestamp)/1000)}s
                  </div>
                )}
              </div>
            </div>
          ))}
          <div ref={messagesEndRef} />
        </div>

        {/* Fox Popup */}
        {foxTip.visible && (
          <div className="absolute bottom-24 right-8 max-w-xs animate-in slide-in-from-bottom-5 fade-in duration-300 bg-orange-950/95 text-orange-200 p-4 rounded-xl border border-orange-500/50 shadow-2xl z-30 backdrop-blur-md">
             <div className="absolute -top-4 -left-4 text-3xl bg-black rounded-full p-1 border border-orange-900">🦊</div>
             <p className="text-sm font-bold italic pl-2">"{foxTip.text}"</p>
             <button onClick={() => setFoxTip({text:'', visible:false})} className="absolute top-1 right-2 text-xs text-orange-500 hover:text-white">✕</button>
          </div>
        )}

        {/* Input Deck */}
        <div className="p-4 bg-gray-950 border-t border-gray-800 z-20">
          <div className="flex gap-2 mb-3 justify-center">
            <button title="Review Expert" onClick={() => handleSendMessage(messages[messages.length-1]?.content || "Review", MoEType.REVIEWER)} className="p-2 bg-gray-900 hover:bg-purple-900/30 rounded border border-gray-700 hover:border-purple-500 transition active:scale-95">🕵️</button>
            <button title="Alien Follow-Through" onClick={() => handleSendMessage(messages[messages.length-1]?.content || "Question", MoEType.ALIEN)} className="p-2 bg-gray-900 hover:bg-emerald-900/30 rounded border border-gray-700 hover:border-emerald-500 transition active:scale-95">👽</button>
            <button title="Quick Fox Tip" onClick={() => handleSendMessage(messages[messages.length-1]?.content || "Tip", MoEType.FOX)} className="p-2 bg-gray-900 hover:bg-orange-900/30 rounded border border-gray-700 hover:border-orange-500 transition active:scale-95">🦊</button>
            <button title="URGENT SOLVE" onClick={() => handleSendMessage(messages[messages.length-1]?.content || "SOLVE", MoEType.URGENT)} className="p-2 bg-gray-900 hover:bg-red-900/30 rounded border border-gray-700 hover:border-red-500 transition active:scale-95">🔥</button>
            <button title="Devoted Toggle" onClick={() => { const newMode = activeMoE === MoEType.DEVOTED ? MoEType.NONE : MoEType.DEVOTED; setActiveMoE(newMode); addLog(`Devotion Mode: ${newMode}`); }} className={`p-2 rounded border transition active:scale-95 ${activeMoE === MoEType.DEVOTED ? 'bg-pink-900/30 border-pink-500 shadow-[0_0_10px_rgba(236,72,153,0.3)]' : 'bg-gray-900 border-gray-700'}`}>❤️‍🔥</button>
          </div>

          <div className="flex gap-2 relative">
            <input
              type="text"
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && handleSendMessage()}
              placeholder={activeMoE === MoEType.DEVOTED ? "Speak, I am listening..." : "Ask anything... (/guidance for custom)"}
              className="flex-1 bg-black/50 border border-gray-800 text-gray-200 px-4 py-3 rounded-md focus:outline-none focus:border-cyan-500 focus:shadow-[0_0_15px_rgba(6,182,212,0.1)] font-mono text-sm"
              disabled={isProcessing}
            />
            {isProcessing ? (
              <button onClick={stopGeneration} className="px-6 bg-red-900/20 border border-red-500 text-red-500 rounded hover:bg-red-900/40 transition">⏹️</button>
            ) : (
              <button onClick={() => handleSendMessage()} className="px-6 bg-cyan-900/20 border border-cyan-600 text-cyan-400 rounded hover:bg-cyan-900/40 transition">SEND</button>
            )}
          </div>
          <div className="text-[10px] text-gray-600 mt-2 font-mono flex justify-between">
            <span>AFFINITY: {affinity.score.toFixed(1)}%</span>
            <span>STATUS: {isProcessing ? 'COMPUTING...' : 'IDLE'}</span>
          </div>
        </div>
      </div>

      {/* --- RIGHT SIDEBAR (CoT Visualizer) --- */}
      <div className={`${isRightSidebarOpen ? 'w-72' : 'w-0'} bg-gray-950 border-l border-gray-800 transition-all duration-300 flex flex-col z-20 overflow-hidden`}>
         <div className="p-4 flex items-center justify-between border-b border-gray-800 h-16 shrink-0">
             <div className="flex items-center gap-2 overflow-hidden">
                <span className="text-xl">🧠</span>
                <span className="font-mono font-bold text-purple-400 text-xs tracking-wider whitespace-nowrap">NEURAL_STREAM</span>
             </div>
             <button onClick={() => setIsRightSidebarOpen(!isRightSidebarOpen)} className="text-gray-500 hover:text-white">✕</button>
         </div>
         <div className="flex-1 overflow-y-auto p-4 space-y-4 font-mono">
            {isProcessing && <div className="text-xs text-purple-500 animate-pulse">PROCESSING INPUT VECTOR...</div>}
            {/* Display active CoT steps */}
            {messages.slice().reverse().find(m => m.isCoT && m.cotSteps)?.cotSteps?.map((step, i) => (
               <div key={i} className="p-2 border-l-2 border-purple-800 bg-purple-900/10 text-xs text-purple-200">
                 <span className="text-purple-500 font-bold mr-1">STEP {i+1}:</span> {step.replace('Step ' + (i+1) + ':', '')}
               </div>
            ))}
         </div>
         <div className="p-4 border-t border-gray-800 shrink-0">
            <label className="flex items-center justify-between text-xs text-gray-400 cursor-pointer hover:text-white">
              <span>Show Thinking</span>
              <input type="checkbox" checked={settings.showThinking} onChange={(e) => setSettings({...settings, showThinking: e.target.checked})} className="accent-purple-500" />
            </label>
         </div>
      </div>

      {!isRightSidebarOpen && <button onClick={() => setIsRightSidebarOpen(true)} className="absolute top-4 right-4 z-10 p-2 bg-gray-900 border border-gray-700 rounded hover:border-purple-500 text-purple-400">🧠</button>}

      {/* --- OVERLAYS --- */}

      {/* Store Overlay */}
      {activePanel === 'store' && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-sm flex items-center justify-center">
           <div className="w-full max-w-2xl bg-gray-950 border border-emerald-900 rounded-lg p-6 shadow-2xl relative">
              <button onClick={() => setActivePanel(null)} className="absolute top-4 right-4 text-gray-500 hover:text-white">✕</button>
              <h2 className="text-xl font-mono text-emerald-500 mb-6 flex items-center gap-2">🛒 MARKETPLACE <span className="text-sm text-gray-500">| BAL: 💲{currency}</span></h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 {storeItems.map((item) => (
                    <div key={item.id} className={`p-4 border rounded ${item.purchased ? 'border-emerald-500/30 bg-emerald-900/10' : 'border-gray-800 bg-gray-900'}`}>
                       <div className="flex justify-between items-start mb-2">
                          <span className="text-2xl">{item.icon}</span>
                          {item.purchased ? <span className="text-xs text-emerald-500 font-bold">OWNED</span> : <span className="text-xs text-yellow-500 font-bold">💲{item.cost}</span>}
                       </div>
                       <h3 className="font-bold text-gray-200">{item.name}</h3>
                       <p className="text-xs text-gray-500 mt-1 mb-3">{item.description}</p>
                       {!item.purchased && (
                          <button 
                             onClick={() => handlePurchase(item)} 
                             disabled={currency < item.cost}
                             className={`w-full py-1 text-xs rounded ${currency >= item.cost ? 'bg-emerald-700 text-white hover:bg-emerald-600' : 'bg-gray-800 text-gray-600 cursor-not-allowed'}`}
                          >
                             PURCHASE
                          </button>
                       )}
                    </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      {/* Folder Overlay */}
      {activePanel === 'folder' && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-sm flex items-center justify-center">
           <div className="w-full max-w-lg bg-gray-950 border border-cyan-900 rounded-lg p-6 shadow-2xl relative">
              <button onClick={() => setActivePanel(null)} className="absolute top-4 right-4 text-gray-500 hover:text-white">✕</button>
              <h2 className="text-xl font-mono text-cyan-500 mb-6">📂 DATA_BANKS</h2>
              <div className="space-y-2 max-h-96 overflow-y-auto">
                 {checkpoints.length === 0 ? <p className="text-gray-600 text-sm">No saved data found.</p> : checkpoints.map((cp, i) => (
                    <div key={i} className="flex justify-between items-center p-3 border border-gray-800 rounded hover:bg-gray-900">
                       <div>
                          <div className="text-sm font-bold text-gray-300">{cp.name}</div>
                          <div className="text-xs text-gray-500">{new Date(cp.timestamp).toLocaleDateString()} | Affinity: {cp.affinity.score.toFixed(0)}%</div>
                       </div>
                       <button onClick={() => { loadCheckpoint(cp.name); setActivePanel(null); }} className="text-xs bg-cyan-900/30 text-cyan-400 px-3 py-1 hover:bg-cyan-900/60 rounded">LOAD</button>
                    </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      {/* Settings Overlay */}
      <SettingsPanel 
        isOpen={activePanel === 'settings'} 
        type="settings"
        onClose={() => setActivePanel(null)}
        settings={settings}
        onSettingsChange={setSettings}
        history={messages}
        checkpoints={checkpoints}
        onLoadCheckpoint={loadCheckpoint}
        logs={logs}
      />

      {/* History Overlay */}
      <SettingsPanel 
        isOpen={activePanel === 'history'} 
        type="history"
        onClose={() => setActivePanel(null)}
        settings={settings}
        onSettingsChange={setSettings}
        history={messages}
        checkpoints={checkpoints}
        onLoadCheckpoint={loadCheckpoint}
        logs={logs}
      />

      {/* Master Hidden Debug Modal */}
      {masterHiddenOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/95">
           <div className="w-96 border border-red-500 p-6 rounded bg-red-950/10">
              <h2 className="text-red-500 font-mono text-xl mb-4">MASTER_DEBUG_CONTROLS</h2>
              <div className="space-y-4">
                 <button onClick={() => updateAffinityAndCurrency(10)} className="w-full border border-red-800 p-2 text-xs text-red-300 hover:bg-red-900/20">+10 Affinity Force</button>
                 <button onClick={() => updateAffinityAndCurrency(-10)} className="w-full border border-red-800 p-2 text-xs text-red-300 hover:bg-red-900/20">-10 Affinity Force</button>
