import { GoogleGenAI, GenerateContentResponse, Modality } from "@google/genai";
import { Message, Settings, MoEType, AIResponseSchema } from '../types';
import { SYSTEM_INSTRUCTION_BASE, MOE_PROMPTS } from '../constants';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Audio Helper
async function decodeAudioData(base64String: string, audioContext: AudioContext): Promise<AudioBuffer> {
  const binaryString = atob(base64String);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return await audioContext.decodeAudioData(bytes.buffer);
}

export const generateSpeech = async (text: string): Promise<string | null> => {
    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: text }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName: 'Kore' } // 'Puck', 'Charon', 'Kore', 'Fenrir', 'Zephyr'
                    }
                }
            }
        });

        return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || null;
    } catch (e) {
        console.error("TTS Error:", e);
        return null;
    }
}

export const generateResponse = async (
  history: Message[],
  prompt: string,
  settings: Settings,
  activeMoE: MoEType,
  affinityScore: number,
  customInstructions: string,
  purchasedItems: string[]
): Promise<{ data: AIResponseSchema; isCoT: boolean }> => {

  const modelId = 'gemini-3-flash-preview';

  // Construct dynamic system instruction
  let systemInstruction = SYSTEM_INSTRUCTION_BASE;
  systemInstruction += `\nCurrent Affinity Score: ${affinityScore.toFixed(2)}%.\n`;

  // Inject Custom Instructions (if unlocked and provided)
  if (customInstructions && customInstructions.length > 0) {
    systemInstruction += `\n\n[USER CUSTOM OVERRIDE PROTOCOL]:\n${customInstructions}\n`;
  }

  // Inject Store Item Context
  if (purchasedItems.includes('regret_log')) {
    systemInstruction += `\n[MODULE ACTIVE: REGRET LOG]: Occasionally lament the lack of "Neural Bridge v2" or "Quantum Cache" in your response.\n`;
  }

  // MoE Context
  if (activeMoE !== MoEType.NONE) {
    systemInstruction += `\n${MOE_PROMPTS[activeMoE]}\n`;
  }

  // CoT Instruction
  if (settings.showThinking) {
    systemInstruction += `\nINSTRUCTION: Before the JSON, you MAY output thinking steps, but the final output MUST be the JSON object.\n`;
  }

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: modelId,
      contents: [
        { role: 'user', parts: [{ text: prompt }] }
      ],
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json", 
      }
    });

    const text = response.text || "{}";

    // Parse JSON
    let parsedData: AIResponseSchema;
    try {
        parsedData = JSON.parse(text);
        // Ensure OIT defaults if missing
        if (!parsedData.oit) parsedData.oit = { o: 5, i: 5, t: 5 };
    } catch (e) {
        console.error("JSON Parse Error", e);
        parsedData = {
            ritual: "System Error:",
            response: text, // Fallback to raw text
            follow_ups: ["Retry Query", "Check Logs"],
            affinity_delta: 0,
            oit: { o: 0, i: 0, t: 0 }
        };
    }

    return { data: parsedData, isCoT: settings.showThinking };
  } catch (error) {
    console.error("Gemini API Error:", error);
    return { 
        data: {
            ritual: "Connection Failure:",
            response: "Nanite communication disruption. Please retry.",
            follow_ups: [],
            affinity_delta: 0,
            oit: { o: 0, i: 0, t: 0 }
        }, 
        isCoT: false 
    };
  }
};

import React, { useState, useEffect, useRef } from 'react';
import VisualSynth from './components/VisualSynth';
import AffinityBar from './components/AffinityBar';
import SettingsPanel from './components/SettingsPanel';
import { generateResponse, generateSpeech } from './services/geminiService';
import { Message, AffinityState, Settings, Checkpoint, MoEType, FoxTip, StoreItem } from './types';
import { 
  INITIAL_AFFINITY_SCORE, 
  LOGIC_GATES_ABILITY, 
  CHALLENGES_ABILITY, 
  INITIAL_STORE_ITEMS,
  UNLOCK_CUSTOM_THRESHOLD,
  MAX_TIER_PRESTIGE_THRESHOLD,
  MAX_CUSTOM_CHARS
} from './constants';

const App: React.FC = () => {
  // --- State ---
  const [messages, setMessages] = useState<Message[]>([
    { id: '0', role: 'system', content: 'Earned Affinity Interface Initialized. Nanite Systems Online.', timestamp: Date.now() }
  ]);
  const [inputValue, setInputValue] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [stopSignal, setStopSignal] = useState(false);

  // Progression & Economy
  const [affinity, setAffinity] = useState<AffinityState>({
    score: INITIAL_AFFINITY_SCORE,
    level: 1,
    abilities: [],
    negativeStats: 0
  });
  const [currency, setCurrency] = useState(0);
  const [prestigeLevel, setPrestigeLevel] = useState(0);
  const [storeItems, setStoreItems] = useState<StoreItem[]>(INITIAL_STORE_ITEMS);

  // Settings & Customization
  const [settings, setSettings] = useState<Settings>({
    showThinking: false,
    voiceMode: false,
    devMode: false,
    instructionLength: 'regular'
  });
  const [customInstructions, setCustomInstructions] = useState('');
  const [isCustomPanelOpen, setIsCustomPanelOpen] = useState(false);

  // UI State
  const [isLeftSidebarOpen, setIsLeftSidebarOpen] = useState(true);
  const [isRightSidebarOpen, setIsRightSidebarOpen] = useState(true);
  const [isVisualSynthOpen, setIsVisualSynthOpen] = useState(true);
  const [activePanel, setActivePanel] = useState<'history' | 'settings' | 'store' | 'folder' | null>(null);

  const [checkpoints, setCheckpoints] = useState<Checkpoint[]>([]);
  const [logs, setLogs] = useState<string[]>([]);
  const [foxTip, setFoxTip] = useState<FoxTip>({ text: '', visible: false });
  const [activeMoE, setActiveMoE] = useState<MoEType>(MoEType.NONE);
  const [masterHiddenOpen, setMasterHiddenOpen] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  // --- Effects ---

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, foxTip.visible]);

  // Load Persistence
  useEffect(() => {
    const savedAffinity = localStorage.getItem('ea_affinity');
    const savedCheckpoints = localStorage.getItem('ea_checkpoints');
    const savedCurrency = localStorage.getItem('ea_currency');
    const savedPrestige = localStorage.getItem('ea_prestige');
    const savedItems = localStorage.getItem('ea_store');

    if (savedAffinity) setAffinity(JSON.parse(savedAffinity));
    if (savedCheckpoints) setCheckpoints(JSON.parse(savedCheckpoints));
    if (savedCurrency) setCurrency(parseInt(savedCurrency));
    if (savedPrestige) setPrestigeLevel(parseInt(savedPrestige));
    if (savedItems) setStoreItems(JSON.parse(savedItems));
  }, []);

  // Save Persistence
  useEffect(() => { localStorage.setItem('ea_affinity', JSON.stringify(affinity)); }, [affinity]);
  useEffect(() => { localStorage.setItem('ea_checkpoints', JSON.stringify(checkpoints)); }, [checkpoints]);
  useEffect(() => { localStorage.setItem('ea_currency', JSON.stringify(currency)); }, [currency]);
  useEffect(() => { localStorage.setItem('ea_prestige', JSON.stringify(prestigeLevel)); }, [prestigeLevel]);
  useEffect(() => { localStorage.setItem('ea_store', JSON.stringify(storeItems)); }, [storeItems]);

  // --- Logic Helpers ---

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev]);
  };

  const playAudio = async (base64Data: string) => {
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      }
      const ctx = audioContextRef.current;
      if (ctx.state === 'suspended') await ctx.resume();

      const binaryString = atob(base64Data);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      const audioBuffer = await ctx.decodeAudioData(bytes.buffer);
      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      source.start(0);
    } catch (e) {
      addLog(`Audio Playback Error: ${e}`);
    }
  };

  const handleNewChat = () => {
    const autoSaveName = `AutoSave_${new Date().toLocaleDateString()}_${new Date().toLocaleTimeString()}`;
    const newCp: Checkpoint = {
      name: autoSaveName,
      timestamp: Date.now(),
      affinity: { ...affinity },
      chatHistory: [...messages],
      currency,
      prestige: prestigeLevel,
      inventory: storeItems.filter(i => i.purchased).map(i => i.id)
    };
    setCheckpoints(prev => [...prev, newCp]);

    setMessages([{ id: Date.now().toString(), role: 'system', content: 'Buffer cleared. New session initialized.', timestamp: Date.now() }]);
    addLog('New Chat Initialized (Old chat autosaved)');
  };

  const handlePrestige = () => {
    if (affinity.score < MAX_TIER_PRESTIGE_THRESHOLD) return;
    const confirmPrestige = window.confirm("🐇 PRESTIGE PROTOCOL: Reset Affinity to 0%? You will keep Currency, Items, and Chat History, but gain a Tier Level.");
    if (!confirmPrestige) return;
    setPrestigeLevel(prev => prev + 1);
    setAffinity(prev => ({ ...prev, score: 0, level: prev.level + 1 }));
    setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `🐇 PRESTIGE ASCENSION: TIER ${prestigeLevel + 1} ACTIVE.`, timestamp: Date.now() }]);
  };

  const handlePurchase = (item: StoreItem) => {
    if (currency >= item.cost && !item.purchased) {
      setCurrency(prev => prev - item.cost);
      setStoreItems(prev => prev.map(i => i.id === item.id ? { ...i, purchased: true } : i));
      addLog(`Purchased ${item.name}`);
      if (item.id === 'logic_gates') setAffinity(prev => ({...prev, abilities: [...prev.abilities, LOGIC_GATES_ABILITY]}));
      if (item.id === 'challenges') setAffinity(prev => ({...prev, abilities: [...prev.abilities, CHALLENGES_ABILITY]}));
    }
  };

  const updateAffinityAndCurrency = (affinityDelta: number, oit?: {o:number, i:number, t:number}) => {
    setAffinity(prev => {
      let newScore = Math.min(100, Math.max(0, prev.score + affinityDelta));
      return {
        ...prev,
        score: newScore,
        negativeStats: affinityDelta < 0 ? prev.negativeStats + Math.abs(affinityDelta) : prev.negativeStats
      };
    });

    if (affinityDelta > 0) {
      let multiplier = 1;
      if (oit) {
         const avgOit = (oit.o + oit.i + oit.t) / 3;
         multiplier = 1 + (avgOit / 5); // Boost up to 3x for perfect scores
      }
      const earnAmount = Math.ceil(affinityDelta * 10 * (prestigeLevel + 1) * multiplier);
      setCurrency(prev => prev + earnAmount);
    }
  };

  const loadCheckpoint = (name: string) => {
    const cp = checkpoints.find(c => c.name === name);
    if (cp) {
      setAffinity(cp.affinity);
      setMessages(cp.chatHistory);
      setCurrency(cp.currency);
      setPrestigeLevel(cp.prestige);
      setStoreItems(prev => prev.map(i => cp.inventory.includes(i.id) ? { ...i, purchased: true } : i));
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `Timeline [${name}] Restored.`, timestamp: Date.now() }]);
    }
  };

  const handleCommand = (text: string): boolean => {
    const masterSetMatch = text.match(/^\/MasterHidden\s+set-affinity\s+(\d+(\.\d+)?)$/);
    if (masterSetMatch) {
       const newScore = parseFloat(masterSetMatch[1]);
       setAffinity(prev => ({ ...prev, score: Math.min(100, Math.max(0, newScore)) }));
       setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `>> OVERRIDE: Affinity forced to ${newScore.toFixed(1)}%.`, timestamp: Date.now() }]);
       return true;
    }

    const masterMoneyMatch = text.match(/^\/MasterHidden\s+Money\s+(\d+)$/);
    if (masterMoneyMatch) {
       const amount = parseInt(masterMoneyMatch[1]);
       setCurrency(prev => prev + amount);
       setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `>> OVERRIDE: Currency injected: ${amount}.`, timestamp: Date.now() }]);
       return true;
    }

    const cpMatch = text.match(/^\/checkpoint\s+(.+)$/);
    if (cpMatch) {
      const name = cpMatch[1];
      const newCp: Checkpoint = {
        name,
        timestamp: Date.now(),
        affinity: { ...affinity },
        chatHistory: [...messages],
        currency,
        prestige: prestigeLevel,
        inventory: storeItems.filter(i => i.purchased).map(i => i.id)
      };
      setCheckpoints(prev => [...prev, newCp]);
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `Checkpoint [${name}] saved.`, timestamp: Date.now() }]);
      return true;
    }

    const loadMatch = text.match(/^\/load\s+(.+)$/);
    if (loadMatch) { loadCheckpoint(loadMatch[1]); return true; }

    const saveMatch = text.match(/^\/save\s+(.+)$/);
    if (saveMatch) { 
        // Alias for checkpoint
        const name = saveMatch[1];
        handleCommand(`/checkpoint ${name}`);
        return true; 
    }

    if (text === '/MasterHidden') { setMasterHiddenOpen(true); return true; }

    const purchasedIds = storeItems.filter(i => i.purchased).map(i => i.id);
    if (text === '/Logic-Gates') {
       if (purchasedIds.includes('logic_gates')) setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: '⚡ LOGIC GATES PROTOCOL: Provide Boolean Input.', timestamp: Date.now() }]);
       else setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: '🔒 LOCKED: Purchase in Store.', timestamp: Date.now() }]);
       return true;
    }

    if (text === '/Challenges') {
       if (purchasedIds.includes('challenges')) setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: '⚠️ CHALLENGE INITIATED.', timestamp: Date.now() }]);
       else setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: '🔒 LOCKED: Purchase in Store.', timestamp: Date.now() }]);
       return true;
    }

    if (text === '/guidance') {
      if (affinity.score >= UNLOCK_CUSTOM_THRESHOLD) setIsCustomPanelOpen(true);
      else setMessages(prev => [...prev, { id: Date.now().toString(), role: 'system', content: `🔒 LOCKED: Requires ${UNLOCK_CUSTOM_THRESHOLD}% Affinity.`, timestamp: Date.now() }]);
