import { GoogleGenAI, GenerateContentResponse, Modality } from "@google/genai";
import { Message, Settings, MoEType, AIResponseSchema } from '../types';
import { SYSTEM_INSTRUCTION_BASE, MOE_PROMPTS } from '../constants';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Audio Helper
async function decodeAudioData(base64String: string, audioContext: AudioContext): Promise<AudioBuffer> {
  const binaryString = atob(base64String);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return await audioContext.decodeAudioData(bytes.buffer);
}

// Helper to clean markdown and special chars for TTS
function cleanTextForTTS(text: string): string {
    return text
        .replace(/[*#`_]/g, '') // Remove basic markdown symbols
        .replace(/\[.*?\]/g, '') // Remove potential [bracket] notes
        .replace(/<.*?>/g, '') // Remove HTML tags
        .replace(/\s+/g, ' ') // Collapse whitespace
        .trim();
}

export const generateSpeech = async (text: string): Promise<string | null> => {
    try {
        const cleanedText = cleanTextForTTS(text);
        if (!cleanedText) return null;

        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: cleanedText }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName: 'Kore' } // 'Puck', 'Charon', 'Kore', 'Fenrir', 'Zephyr'
                    }
                }
            }
        });

        return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || null;
    } catch (e) {
        console.error("TTS Error:", e);
        return null;
    }
}

export const generateResponse = async (
  history: Message[],
  prompt: string,
  settings: Settings,
  activeMoE: MoEType,
  affinityScore: number,
  customInstructions: string,
  purchasedItems: string[]
): Promise<{ data: AIResponseSchema; isCoT: boolean; cotText: string }> => {

  // Use the fast lite model (Corrected ID)
  const modelId = 'gemini-2.0-flash-lite-preview-02-05';

  // Construct dynamic system instruction
  let systemInstruction = SYSTEM_INSTRUCTION_BASE;
  systemInstruction += `\nCurrent Affinity Score: ${affinityScore.toFixed(2)}%.\n`;

  // Inject Custom Instructions
  if (customInstructions && customInstructions.length > 0) {
    systemInstruction += `\n\n[USER CUSTOM OVERRIDE PROTOCOL]:\n${customInstructions}\n`;
  }

  // Inject Store Item Context
  if (purchasedItems.includes('regret_log')) {
    systemInstruction += `\n[MODULE ACTIVE: REGRET LOG]: Occasionally lament the lack of "Neural Bridge v2" or "Quantum Cache" in your response.\n`;
  }

  // MoE Context
  if (activeMoE !== MoEType.NONE) {
    systemInstruction += `\n${MOE_PROMPTS[activeMoE]}\n`;
  }

  // CoT Instruction
  if (settings.showThinking) {
    // Relax the strict JSON requirement to allow thinking steps before JSON
    systemInstruction = systemInstruction.replace(
        "You must respond in valid JSON format ONLY. Do not output markdown code blocks.", 
        "You must respond in valid JSON format, preceded by your thinking process."
    );
    systemInstruction += `\nINSTRUCTION: You must first output your thinking process steps as plain text (e.g., "Step 1: ..."). Then, output the final response in valid JSON format. Do not wrap the JSON in markdown code blocks if possible.\n`;
  }

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: modelId,
      contents: [
        { role: 'user', parts: [{ text: prompt }] }
      ],
      config: {
        systemInstruction: systemInstruction,
        // When showing thinking, we can't force strict JSON mimeType because the thinking text is not JSON.
        // We rely on the model following instructions to output text then JSON.
        responseMimeType: settings.showThinking ? "text/plain" : "application/json", 
      }
    });

    const fullText = response.text || "{}";
    let jsonText = fullText;
    let cotText = "";

    // Parse CoT and JSON
    if (settings.showThinking) {
        // Try to find the start of the JSON object
        const jsonStartIndex = fullText.indexOf('{');
        const jsonEndIndex = fullText.lastIndexOf('}');

        if (jsonStartIndex !== -1 && jsonEndIndex !== -1) {
            cotText = fullText.substring(0, jsonStartIndex).trim();
            jsonText = fullText.substring(jsonStartIndex, jsonEndIndex + 1);

            // Cleanup CoT text (remove trailing markdown indicators if they bled into the thinking part)
            cotText = cotText.replace(/```json/g, '').replace(/```/g, '').trim();
        }
    }

    // Clean markdown if present
    jsonText = jsonText.replace(/```json/g, '').replace(/```/g, '').trim();

    // Parse JSON
    let parsedData: AIResponseSchema;
    try {
        parsedData = JSON.parse(jsonText);
        // Ensure OIT defaults if missing
        if (!parsedData.oit) parsedData.oit = { o: 5, i: 5, t: 5 };
    } catch (e) {
        console.error("JSON Parse Error", e);
        // Fallback: treat the whole text as response if JSON fails
        parsedData = {
            ritual: "Parsing Error:",
            response: fullText, 
            follow_ups: ["Retry Query"],
            affinity_delta: 0,
            oit: { o: 0, i: 0, t: 0 }
        };
    }

    return { data: parsedData, isCoT: settings.showThinking, cotText };
  } catch (error) {
    console.error("Gemini API Error:", error);
    return { 
        data: {
            ritual: "Connection Failure:",
            response: "Nanite communication disruption. Please retry.",
            follow_ups: [],
            affinity_delta: 0,
            oit: { o: 0, i: 0, t: 0 }
        }, 
        isCoT: false,
        cotText: ""
    };
  }
};

