                     const lastBrace = str.lastIndexOf('}');
                     if (firstBrace >= 0 && lastBrace > firstBrace) {
                         try {
                             return JSON.parse(str.substring(firstBrace, lastBrace + 1));
                         } catch (e4) {
                             throw e; // Give up
                         }
                     }
                     throw e;
                 }
            }
        }
    };

