         {/* Bottom Sidebar Commands - Visible only when open for cleaner look, or icon only */}
         {isLeftSidebarOpen && (
             <div className="p-3 border-t border-gray-800 bg-gray-950 space-y-2">
                 <div className="text-[10px] text-gray-500 font-mono mb-1">QUICK_CMDS</div>
