                     <button onClick={() => injectCommand('/Logic-Gates')} className="px-2 py-1 bg-gray-900 border border-yellow-700 rounded text-[10px] text-yellow-400 hover:text-yellow-200 whitespace-nowrap flex-1">/Logic</button>
