                <div className="whitespace-pre-wrap leading-relaxed">{msg.content}</div>

                {/* Audio Button for Non-User Messages */}
                {(msg.role === 'model' || msg.role === 'expert' || msg.role === 'alien') && (
                    <div className="mt-2 flex items-center justify-between border-t border-gray-800/30 pt-1">
                        <button 
                            onClick={() => handleReadAloud(msg)} 
                            className={`text-[10px] px-2 py-0.5 rounded border transition-colors ${playingMessageId === msg.id ? 'bg-cyan-900/50 text-white border-cyan-500 animate-pulse' : 'bg-transparent text-gray-500 border-gray-800 hover:text-cyan-400 hover:border-cyan-600'}`}
                        >
                            {playingMessageId === msg.id ? '⏹️ STOP AUDIO' : '✨ READ ALOUD'}
                        </button>

                        {/* Feedback Mechanism */}
                        <div className="flex gap-2">
                            <button 
                                onClick={() => handleFeedback(msg.id, 'up')}
                                disabled={!!msg.feedback}
                                className={`text-xs hover:scale-110 transition-transform ${msg.feedback === 'up' ? 'opacity-100 grayscale-0' : msg.feedback ? 'opacity-20 grayscale' : 'opacity-50 hover:opacity-100'}`}
                                title="Positive Feedback (+Affinity)"
                            >
                                👍
                            </button>
                            <button 
                                onClick={() => handleFeedback(msg.id, 'down')}
                                disabled={!!msg.feedback}
                                className={`text-xs hover:scale-110 transition-transform ${msg.feedback === 'down' ? 'opacity-100 grayscale-0' : msg.feedback ? 'opacity-20 grayscale' : 'opacity-50 hover:opacity-100'}`}
                                title="Negative Feedback (-Affinity)"
                            >
                                👎
                            </button>
                        </div>
                    </div>
