     ACHIEVEMENTS_LIST.forEach(ach => {
         if (!updatedUnlocked.includes(ach.id)) {
             if (ach.condition({ messages, affinity, currency })) {
                 updatedUnlocked.push(ach.id);
                 newlyUnlocked = ach.title;
