import { GoogleGenAI, LiveServerMessage, Modality } from "@google/genai";
import { MOE_PROMPTS, AGENT_VOICES } from '../constants';
import { MoEType } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export class LiveSession {
  private session: any = null;
  private inputContext: AudioContext | null = null;
  private outputContext: AudioContext | null = null;
  private outputNode: GainNode | null = null;
  private nextStartTime = 0;
  private sources = new Set<AudioBufferSourceNode>();
  private active = false;
  private onStatusChange: (status: boolean) => void;

  constructor(onStatusChange: (status: boolean) => void) {
    this.onStatusChange = onStatusChange;
  }

  async connect(activeMoE: MoEType) {
    if (this.active) return;

    // Setup Audio Contexts
    this.inputContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
    this.outputContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    this.outputNode = this.outputContext.createGain();
    this.outputNode.connect(this.outputContext.destination);

    // Get Mic Stream
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

    // Construct System Instruction based on Persona
    const personaInstruction = MOE_PROMPTS[activeMoE] || "";
    const voiceName = AGENT_VOICES[activeMoE] || 'Kore';

    const systemInstruction = `You are a real-time voice interface for the Earned Affinity system. 
    ${personaInstruction}
    Keep responses concise, conversational, and aligned with your identity. 
    Do not output JSON here, just speak naturally.`;

    const sessionPromise = ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      callbacks: {
        onopen: () => {
          console.log('Live Session Opened');
          this.active = true;
          this.onStatusChange(true);

          // Setup Input Processing
          if (!this.inputContext) return;
          const source = this.inputContext.createMediaStreamSource(stream);
          const scriptProcessor = this.inputContext.createScriptProcessor(4096, 1, 1);

          scriptProcessor.onaudioprocess = (e) => {
            if (!this.active) return;
            const inputData = e.inputBuffer.getChannelData(0);
            const pcmBlob = this.createBlob(inputData);

            sessionPromise.then((session) => {
               session.sendRealtimeInput({ media: pcmBlob });
            });
          };

          source.connect(scriptProcessor);
          scriptProcessor.connect(this.inputContext.destination);
        },
        onmessage: async (msg: LiveServerMessage) => {
           const audioData = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
           if (audioData) {
               await this.playAudio(audioData);
           }

           if (msg.serverContent?.interrupted) {
               this.stopAudio();
           }
        },
        onclose: () => {
           console.log('Live Session Closed');
           this.disconnect();
        },
        onerror: (err) => {
           console.error('Live Session Error', err);
           this.disconnect();
        }
      },
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
            voiceConfig: {
                prebuiltVoiceConfig: { voiceName: voiceName }
            }
        },
        systemInstruction: systemInstruction,
      }
    });

    this.session = sessionPromise;
  }

  createBlob(data: Float32Array): { data: string, mimeType: string } {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
        int16[i] = data[i] * 32768;
    }

    // Simple btoa for raw bytes
    let binary = '';
    const bytes = new Uint8Array(int16.buffer);
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
        binary += String.fromCharCode(bytes[i]);
    }

    return {
        data: btoa(binary),
        mimeType: 'audio/pcm;rate=16000'
    };
  }

  async playAudio(base64Data: string) {
      if (!this.outputContext || !this.outputNode) return;

      const binaryString = atob(base64Data);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) { bytes[i] = binaryString.charCodeAt(i); }

      const int16Data = new Int16Array(bytes.buffer);
      const audioBuffer = this.outputContext.createBuffer(1, int16Data.length, 24000);
      const channelData = audioBuffer.getChannelData(0);
      for (let i = 0; i < int16Data.length; i++) {
          channelData[i] = int16Data[i] / 32768.0;
      }

      this.nextStartTime = Math.max(this.nextStartTime, this.outputContext.currentTime);
      const source = this.outputContext.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(this.outputNode);
      source.start(this.nextStartTime);
      this.nextStartTime += audioBuffer.duration;

      this.sources.add(source);
      source.onended = () => this.sources.delete(source);
  }

  stopAudio() {
      this.sources.forEach(s => {
          try { s.stop(); } catch(e) {}
      });
      this.sources.clear();
      this.nextStartTime = 0;
  }

  async disconnect() {
    this.active = false;
    this.onStatusChange(false);
    this.stopAudio();
    if (this.session) {
        // No explicit close method on promise
    }
    if (this.inputContext) {
        try { await this.inputContext.close(); } catch(e) {}
    }
    if (this.outputContext) {
        try { await this.outputContext.close(); } catch(e) {}
    }
    this.inputContext = null;
    this.outputContext = null;
  }
}

import React, { useEffect, useRef } from 'react';
import { MoEType } from '../types';

interface VisualSynthProps {
  isActive: boolean;
  voiceMode: boolean;
  affinity: number;
  activeMoE?: MoEType; // Added to drive chaotic math
}

const VisualSynth: React.FC<VisualSynthProps> = ({ isActive, voiceMode, affinity, activeMoE = MoEType.NONE }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;
    let t = 0;

    const render = () => {
      t += 0.05;
      const width = canvas.width;
      const height = canvas.height;

      // Clear with trail effect
      ctx.fillStyle = 'rgba(5, 5, 5, 0.2)';
      ctx.fillRect(0, 0, width, height);

      // Color based on affinity
      const r = Math.floor(255 - (affinity * 2.5));
      const g = Math.floor(affinity * 2.5);
      const b = 200;

      ctx.strokeStyle = `rgba(${r}, ${g}, ${b}, ${isActive ? 0.9 : 0.3})`;
      ctx.lineWidth = 2;
      ctx.beginPath();

      const baseAmplitude = isActive ? 30 : 5;
      const baseFrequency = voiceMode ? 0.1 : 0.02;

      // Agent-Specific Math Frameworks
      for (let i = 0; i < width; i++) {
        let y = height / 2;

        if (activeMoE === MoEType.ALIEN) {
             // Chaotic, glitchy, high frequency noise
             const noise = Math.random() * (isActive ? 20 : 5);
             y += Math.sin(i * 0.1 + t * 5) * baseAmplitude + noise;
        } else if (activeMoE === MoEType.REVIEWER) {
             // Dense, ordered, square-wave like
             y += Math.sign(Math.sin(i * 0.05 + t)) * baseAmplitude * 0.8;
             y += Math.cos(i * 0.01 + t) * 10;
        } else if (activeMoE === MoEType.DEVOTED) {
             // Resonant, harmonic, flowing
             y += Math.sin(i * 0.02 + t) * baseAmplitude;
             y += Math.sin(i * 0.05 - t) * (baseAmplitude / 2);
        } else if (activeMoE === MoEType.URGENT) {
             // Fast, sharp peaks
             y += Math.tan(i * 0.01 + t * 2) * (isActive ? 10 : 2); // Clamped via bounds usually, but visual artifact is cool
             if (y > height || y < 0) y = height / 2; // clamp
        } else {
             // Standard Sine
             y += Math.sin(i * baseFrequency + t) * baseAmplitude * Math.sin(i * 0.01);
        }

        if (i === 0) ctx.moveTo(i, y);
        else ctx.lineTo(i, y);
      }

      ctx.stroke();

      // Nanite Particles - Density based on agent
      if (isActive) {
        const particleCount = activeMoE === MoEType.ALIEN ? 15 : 5;
        for (let i = 0; i < particleCount; i++) {
            ctx.fillStyle = `rgba(${r},${g},${b}, ${Math.random()})`;
            const px = Math.random() * width;
            // Spread particles more for chaotic agents
            const spread = activeMoE === MoEType.ALIEN ? 100 : 40;
            const py = height / 2 + (Math.random() - 0.5) * spread;
            const size = Math.random() * 2 + 1;
            ctx.fillRect(px, py, size, size);
        }
      }

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => cancelAnimationFrame(animationFrameId);
  }, [isActive, voiceMode, affinity, activeMoE]);

  return (
    <div className="w-full h-32 bg-black relative overflow-hidden border-b border-gray-800">
      <canvas 
        ref={canvasRef} 
        width={800} 
        height={128} 
        className="w-full h-full object-cover"
      />
      <div className="absolute top-2 right-2 text-xs font-mono text-cyan-500 flex flex-col items-end">
        <span>VISUAL_SYNTH // {voiceMode ? 'VOICE_ACTIVE' : 'TEXT_MODE'}</span>
        <span className="text-[10px] opacity-70">PATTERN: {activeMoE}</span>
      </div>
    </div>
  );
};

